const csrf = document.querySelector('meta[name="csrf-token"]').content;
const base = (document.querySelector('meta[name="app-base"]')?.content || '').replace(/\/$/, '');
const app = document.querySelector('#app');
const title = document.querySelector('#page-title');
const modal = document.querySelector('#modal');
const modalForm = document.querySelector('#modal-form');
const search = document.querySelector('#global-search');
const contextMenu = document.querySelector('#context-menu');
const autoReplanStorageKey = 'ipdesigner.autoReplan';
const hostViewStorageKey = 'ipdesigner.hostView';

function storedAutoReplan(){try{return localStorage.getItem(autoReplanStorageKey)==='1';}catch{return false;}}
function saveAutoReplan(value){try{localStorage.setItem(autoReplanStorageKey,value?'1':'0');}catch{}return value;}
function storedHostView(){try{return localStorage.getItem(hostViewStorageKey)==='table'?'table':'cards';}catch{return'cards';}}
function saveHostView(value){try{localStorage.setItem(hostViewStorageKey,value);}catch{}return value;}

const state = { view: 'dashboard', query: '', selectedBlock: null, selectedSubnet: null, selectedSpace: null, selectedNetwork: null, selectedNetworks: new Set(), selectedRouter: null, selectedSite: '', analysis: null, data: {}, topology: null, topologySite: '', topologyViewport: null, topologyViewScope: null, topologyExtent: null, topologyFitWidth: 1500, topologyLabelLayouts: new Map(), relationSource: null, focusId: null, autoReplan: storedAutoReplan(), calculatorResults: {}, hostView: storedHostView(), hostFilters:{q:'',site:'',type:'',status:''} };
const labels = {
  connected:'verbunden mit', routes_to:'routet zu', uses:'nutzt', depends_on:'abhängig von', manages:'verwaltet',
  address_space:'Adressraum', site:'Site', block:'Gruppe', subnet:'Subnetz', host:'Host', router:'Router', service:'Dienst', virtual_network:'Virtuelles Netz',
  planned:'Geplant', active:'Aktiv', degraded:'Beeinträchtigt', inactive:'Inaktiv',
};

function esc(value = '') { return String(value ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
function number(value) { return new Intl.NumberFormat('de-DE').format(Number(value || 0)); }
function optionList(items, selected, placeholder = 'Bitte wählen …') {
  return `<option value="">${placeholder}</option>` + items.map(item => `<option value="${esc(item.value ?? item.id)}" ${(String(item.value ?? item.id) === String(selected ?? '')) ? 'selected' : ''}>${esc(item.label ?? item.name)}</option>`).join('');
}
function siteNameFor(item={}){if(item.site_name)return item.site_name;let siteId=item.site_id;if(!siteId&&item.host_id)siteId=state.data.hosts?.find(host=>Number(host.id)===Number(item.host_id))?.site_id;return state.data.sites?.find(site=>Number(site.id)===Number(siteId))?.name||'';}
function siteOptionLabel(item,label){const site=siteNameFor(item);return site?`${site} · ${label}`:label;}
function badge(status) { return `<span class="badge ${esc(status)}">${esc(labels[status] || status)}</span>`; }
function notify(message, error = false) {
  const box = document.querySelector('#notice');
  const node = document.createElement('div'); node.className = `notice${error ? ' error' : ''}`; node.textContent = message; box.append(node);
  setTimeout(() => node.remove(), 4500);
}
async function api(path, options = {}) {
  const response = await fetch(`${base}/api/${path}`, { ...options, headers: {'Content-Type':'application/json','X-CSRF-Token':csrf,...(options.headers || {})} });
  const payload = await response.json().catch(() => ({error:{message:'Ungültige Serverantwort.'}}));
  if (!response.ok) throw new Error(payload.error?.message || 'Anfrage fehlgeschlagen.');
  return payload.data;
}
async function loadData() {
  const names = ['dashboard','sites','blocks','subnets','hosts','routers','interfaces','virtual-networks','vpn-interfaces','services','reservations','relations','objects','address-spaces','networks'];
  const values = await Promise.all(names.map(name => api(name)));
  names.forEach((name, i) => state.data[name] = values[i]);
  const networkIds=new Set(state.data.networks.map(network=>Number(network.id)));state.selectedNetworks=new Set([...state.selectedNetworks].filter(id=>networkIds.has(Number(id))));
  if (!state.selectedBlock && state.data.blocks[0]) state.selectedBlock = Number(state.data.blocks[0].id);
  if (!state.selectedSpace && state.data['address-spaces'][0]) state.selectedSpace = Number(state.data['address-spaces'][0].id);
}
async function refresh(message) {
  await loadData();
  await render();
  if (message) notify(message);
}
function pageHead(heading, text, actions = '') {
  return `<div class="page-head"><div><h2>${heading}</h2><p>${text}</p></div><div class="actions">${actions}</div></div>`;
}

function routeInfo() {
  const raw=(location.hash||'#dashboard').slice(1);const [view,query='']=raw.split('?');return{view,params:new URLSearchParams(query)};
}
function go(view,params={}) { const query=new URLSearchParams(Object.entries(params).filter(([,value])=>value!==''&&value!==null&&value!==undefined));location.hash=`${view}${query.size?`?${query}`:''}`; }
function scrollToFocus(){if(!state.focusId)return;requestAnimationFrame(()=>document.querySelector('.focused')?.scrollIntoView({block:'center',behavior:'smooth'}));}

function renderDashboard() {
  const d = state.data.dashboard;
  const recentHosts = state.data.hosts.slice(0, 6);
  app.innerHTML = pageHead('Infrastruktur auf einen Blick','Kapazitäten, Objekte und aktueller Planungsstand.') + `
    <div class="stats">
      <div class="stat"><div class="stat-label">Standorte</div><div class="stat-value">${number(d.sites)}</div><div class="stat-note">${number(d.blocks)} Adressbereiche</div></div>
      <div class="stat"><div class="stat-label">Subnetze</div><div class="stat-value">${number(d.subnets)}</div><div class="stat-note">${number(d.usable)} nutzbare Adressen</div></div>
      <div class="stat"><div class="stat-label">Hosts</div><div class="stat-value">${number(d.hosts)}</div><div class="stat-note">${number(d.assigned)} belegte IPs</div></div>
      <div class="stat"><div class="stat-label">Dienste</div><div class="stat-value">${number(d.services)}</div><div class="stat-note">In allen Umgebungen</div></div>
    </div>
    <div class="grid-2">
      <div class="panel"><div class="panel-head"><h3>Globale IPv4-Auslastung</h3><strong>${d.utilization}%</strong></div><div class="panel-body">
        <div class="usage"><div class="usage-track"><div class="usage-fill" style="width:${Math.min(100,d.utilization)}%"></div></div></div>
        <div class="capacity"><div><strong>${number(d.assigned)}</strong><span>Zugewiesen</span></div><div><strong>${number(d.reserved)}</strong><span>Reserviert</span></div><div><strong>${number(d.free)}</strong><span>Frei</span></div><div><strong>${number(d.usable)}</strong><span>Gesamt nutzbar</span></div></div>
      </div></div>
      <div class="panel"><div class="panel-head"><h3>Hosts</h3><button class="button small secondary" data-action="host-add">Host anlegen</button></div>${recentHosts.length ? `<div class="table-wrap"><table><tbody>${recentHosts.map(h=>`<tr><td><strong>${esc(h.name)}</strong><br><span class="mono muted">${esc(h.fqdn)}</span></td><td>${badge(h.status)}</td><td class="mono">${h.interfaces.flatMap(i=>i.ips||[i.ip]).map(esc).join('<br>') || '–'}</td></tr>`).join('')}</tbody></table></div>` : '<div class="empty">Noch keine Hosts angelegt.</div>'}</div>
    </div>`;
}

function renderSites() {
  const q=state.query.toLowerCase();const sites=state.data.sites.filter(site=>!q||[site.name,site.domain_name,site.location,site.description].join(' ').toLowerCase().includes(q));
  app.innerHTML=pageHead('Sites','Jede Site gehört zu genau einem globalen Adressraum und enthält ihre Gruppen, Subnetze und Hosts.',`<button class="button primary" data-action="site-add">Site anlegen</button>`)+`<div class="site-grid">${sites.map(site=>`<article class="panel site-card ${Number(state.focusId)===Number(site.id)?'focused':''} ${site.address_space_id?'':'assignment-required'}"><div class="site-card-head"><div><p class="eyebrow">SITE · ${site.allocation_mode==='cidr'?'CIDR-BLOCK':'IP-RANGE'}</p><h3>${esc(site.name)}</h3><span class="site-domain">${esc(site.domain_name)}</span></div><span class="site-location">${esc(site.location||'Kein Standort')}</span></div><div class="site-space ${site.address_space_id?'':'missing'}">${site.address_space_id?`Adressraum: <strong>${esc(site.address_space_name)}</strong> · ${esc(site.routing_domain)}${site.site_range?` · <span class="mono">${esc(site.allocation_mode==='cidr'?site.site_cidr:site.site_range)}</span>`:''}`:'⚠ Adressraum-Zuordnung erforderlich'}</div><p class="site-description">${esc(site.description||'Keine Beschreibung hinterlegt.')}</p><div class="site-metrics"><div><strong>${number(site.area_count)}</strong><span>Gruppen</span></div><div><strong>${number(site.subnet_count)}</strong><span>Subnetze</span></div><div><strong>${number(site.host_count)}</strong><span>Hosts</span></div><div><strong>${number(site.service_count)}</strong><span>Dienste</span></div></div><div class="site-usage"><div><span>IPv4-Auslastung</span><strong>${site.utilization_percent}%</strong></div><div class="usage-track"><div class="usage-fill" style="width:${Math.min(100,site.utilization_percent)}%"></div></div><small>${number(site.occupied_addresses)} belegt · ${number(site.free_addresses)} frei · ${number(site.usable_addresses)} nutzbar</small></div><div class="card-actions"><button class="button small primary" data-action="site-ipam" data-id="${site.id}" ${site.address_space_id?'':'disabled'}>Adressplanung</button><button class="button small secondary" data-action="site-topology" data-id="${site.id}">Topologie</button><button class="button small secondary" data-action="site-edit" data-id="${site.id}">${site.address_space_id?'Bearbeiten':'Jetzt zuordnen'}</button><button class="button small danger" data-delete="sites" data-id="${site.id}">Löschen</button></div></article>`).join('')||'<div class="panel empty">Keine passenden Sites gefunden.</div>'}</div>`;
  scrollToFocus();
}

function subnetRow(n) {
  return `<tr data-subnet="${n.id}"><td><strong>${esc(n.name)}</strong><br><span class="mono muted">${esc(n.cidr)}</span></td><td>${n.vlan_id ? `VLAN ${n.vlan_id}` : '–'}<br><span class="muted">${esc(n.vrf_name || '')}</span></td><td><div class="usage"><div class="usage-track"><div class="usage-fill" style="width:${Math.min(100,n.utilization)}%"></div></div><span class="usage-label">${number(n.assigned_count)} belegt · ${number(n.free_count)} frei</span></div></td><td><div class="actions"><button class="button small secondary" data-action="subnet-edit" data-id="${n.id}">Bearbeiten</button><button class="button small secondary" data-action="reservation-add" data-id="${n.id}">Reservieren</button><button class="button small danger" data-delete="subnets" data-id="${n.id}">Löschen</button></div></td></tr>`;
}
function renderAddressGrid(subnet) {
  if (!subnet) return '';
  const assigned = new Set(state.data.interfaces.filter(i=>Number(i.subnet_id)===Number(subnet.id)).flatMap(i=>i.ips||[i.ip]));
  const subnetReservations = state.data.reservations.filter(r=>Number(r.subnet_id)===Number(subnet.id));
  const reserved = new Set(subnetReservations.map(r=>r.ip));
  const cells=[];
  if(subnet.size<=256){const start=ipToInt(subnet.network);for(let i=0;i<subnet.size;i++){const ip=intToIp(start+i);const system=(subnet.prefix<=30&&(i===0||i===subnet.size-1));const klass=system?'system':assigned.has(ip)?'used':reserved.has(ip)?'reserved':'';cells.push(`<span class="address-cell ${klass}" title="${ip}"></span>`);}}
  const visual=subnet.size<=256?`<div class="address-grid">${cells.join('')}</div><div class="legend"><span><i style="background:#146c5f"></i>Host</span><span><i style="background:#d5902f"></i>Reserviert</span><span><i style="background:#9da9ae"></i>Netz/Broadcast</span><span><i style="background:#e7ecee"></i>Frei</span></div>`:`<div class="capacity"><div><strong>${number(subnet.assigned_count)}</strong><span>Zugewiesen</span></div><div><strong>${number(subnet.reserved_count)}</strong><span>Reserviert</span></div><div><strong>${number(subnet.free_count)}</strong><span>Frei</span></div><div><strong>${number(subnet.usable)}</strong><span>Nutzbar</span></div></div>`;
  return `<div class="panel" style="margin-top:18px"><div class="panel-head"><h3>Adressbelegung ${esc(subnet.cidr)}</h3></div><div class="panel-body">${visual}</div>${subnetReservations.length?`<div class="table-wrap"><table><thead><tr><th>Reservierte IP</th><th>Bezeichnung</th><th>Grund</th><th></th></tr></thead><tbody>${subnetReservations.map(r=>`<tr><td class="mono">${esc(r.ip)}</td><td>${esc(r.label)}</td><td>${esc(r.reason)}</td><td><div class="actions"><button class="button small secondary" data-action="reservation-edit" data-id="${r.id}">Bearbeiten</button><button class="button small danger" data-delete="reservations" data-id="${r.id}">Löschen</button></div></td></tr>`).join('')}</tbody></table></div>`:''}</div>`;
}
function networkMatchesSite(node){if(!state.selectedSite)return true;if(Number(node.site_id)===Number(state.selectedSite))return true;return state.data.networks.some(child=>Number(child.parent_id)===Number(node.id)&&networkMatchesSite(child));}
function networkRole(n){return n.node_role||(n.node_type==='leaf'?'subnet':'group');}
function networkRoleLabel(n){return({subnet:'Subnetz',aggregate:'Supernetz',l3_subnet:'L3-Subnetz',static_pool:'Statischer Pool',dhcp_pool:'DHCP-Pool',group:'Gruppe'})[networkRole(n)]||'Netzobjekt';}
function networkBranch(parentId=null,depth=0,siteId=null){const nodes=state.data.networks.filter(n=>Number(n.address_space_id)===Number(state.selectedSpace)&&Number(n.site_id)===Number(siteId)&&String(n.parent_id||'')===String(parentId||''));return nodes.map(n=>`<div class="network-branch ${state.selectedNetworks.has(Number(n.id))?'selected':''}" draggable="true" data-network-row="${n.id}"><div class="network-insert-zone before" data-drop-mode="before" data-drop-id="${n.id}"><span>vor „${esc(n.name)}“ einfügen</span></div><label class="network-check" style="--depth:${depth}" title="Für Sammelaktion auswählen"><input type="checkbox" data-network-check="${n.id}" ${state.selectedNetworks.has(Number(n.id))?'checked':''}><span></span></label><button class="network-node ${Number(n.id)===Number(state.selectedNetwork)?'active':''}" style="--depth:${depth}" data-action="network-select" data-id="${n.id}" data-drop-mode="inside" data-drop-id="${n.id}"><span class="node-icon">${networkRole(n)==='subnet'?'◉':networkRole(n)==='l3_subnet'?'⬡':networkRole(n)==='static_pool'?'S':networkRole(n)==='dhcp_pool'?'D':networkRole(n)==='aggregate'?'▣':'◇'}</span><span><strong>${esc(n.name)}</strong><small>${esc(n.cidr)} · ${['static_pool','dhcp_pool'].includes(networkRole(n))?`${esc(n.range_start)}–${esc(n.range_end)}`:networkRole(n)==='subnet'?`${number(n.free_count)} frei`:networkRoleLabel(n)}</small></span><span class="drag-handle" title="Ziehen zum Verschieben oder Verschachteln">⋮⋮</span></button><div class="network-insert-zone after" data-drop-mode="after" data-drop-id="${n.id}"><span>nach „${esc(n.name)}“ einfügen</span></div>${networkBranch(n.id,depth+1,siteId)}</div>`).join('');}
function siteBranches(){const sites=state.data.sites.filter(s=>Number(s.address_space_id)===Number(state.selectedSpace)&&(!state.selectedSite||Number(s.id)===Number(state.selectedSite)));return sites.map(s=>`<section class="site-tree"><div class="site-tree-head" data-site-drop="${s.id}"><span><strong>${esc(s.name)}</strong><small>${esc(s.domain_name)} · hierher ziehen für oberste Ebene</small></span><span class="actions"><button class="button small secondary" data-action="network-plan" data-kind="container" data-root="1" data-site="${s.id}">Gruppe +</button><button class="button small secondary" data-action="network-plan" data-kind="leaf" data-root="1" data-site="${s.id}">Subnetz +</button></span></div>${networkBranch(null,0,s.id)||'<div class="empty compact">Noch keine Netze in dieser Site.</div>'}</section>`).join('');}
function renderPlannerPanel(network){if(!network)return`<div class="panel"><div class="panel-head"><h3>Dynamischer Planer</h3></div><div class="empty">Lege eine optionale Gruppe oder direkt ein Subnetz an. Präfix und Ende werden automatisch berechnet.</div></div>`;return`<div class="panel planner-panel"><div class="panel-head"><h3>Dynamischer Planer</h3><span class="health ok">Dynamisch</span></div><div class="panel-body"><div class="recommendations"><p>Das CIDR wird aus Hostbedarf, Belegung und ${number(network.reserve_percent)} % Reserve berechnet.</p><p>Änderungen werden erst nach einem vollständigen Alt→Neu-Vergleich übernommen.</p></div><button class="button primary wide-button" data-action="replan-current">Gesamtplan neu berechnen</button><button class="button secondary wide-button" data-action="replan-history">Replan-Historie</button>${network.node_type==='leaf'?`<button class="button secondary wide-button" data-action="planned-host" data-id="${network.id}">Host mit nächster freier IP anlegen</button>`:''}</div></div>`;}
function renderVirtualNetworks(){const rows=state.data['virtual-networks']||[],vpnInterfaces=state.data['vpn-interfaces']||[];return`<section class="virtual-networks"><div class="virtual-network-head"><div><p class="eyebrow">RESERVIERTE CIDRs</p><h3>Virtuelle Netze</h3><span>VPN-Transitnetze und Docker-Bridges bleiben fest. Der dynamische Planer behandelt ihre CIDRs als reservierte Lücken und platziert normale Bereiche automatisch davor oder danach.</span></div><div class="actions"><button class="button secondary" data-action="virtual-network-add" data-kind="docker_bridge">Docker-Netz +</button><button class="button primary" data-action="virtual-network-add" data-kind="vpn">VPN-Netz +</button></div></div><div class="virtual-network-grid">${rows.map(v=>{const members=vpnInterfaces.filter(i=>Number(i.virtual_network_id)===Number(v.id));return`<article class="panel virtual-network-card ${esc(v.network_type)}"><div class="panel-head"><div><p class="eyebrow">${v.network_type==='vpn'?'VPN-TRANSIT':'DOCKER BRIDGE'}</p><h3>${esc(v.name)}</h3><span class="mono muted">${esc(v.cidr)}</span></div><span class="virtual-icon">${v.network_type==='vpn'?'VPN':'D'}</span></div><div class="panel-body">${v.network_type==='vpn'?`<p class="virtual-fact">${number(v.interface_count)} Router-Interface${Number(v.interface_count)===1?'':'s'}</p><div class="virtual-members">${members.map(i=>`<span><b>${esc(i.router_name)}</b> · ${esc(i.name)} · <span class="mono">${(i.ips||[i.ip]).map(esc).join(', ')}</span><button class="button small secondary" data-action="vpn-interface-edit" data-id="${i.id}">✎</button><button class="button small danger" data-delete="vpn-interfaces" data-id="${i.id}">×</button></span>`).join('')||'<small>Noch keine Router verbunden.</small>'}</div>`:`<p class="virtual-fact">Besitzer <b>${esc(v.owner_name)}</b> · Gateway <span class="mono">${esc(v.gateway)}</span> · Treiber bridge</p>`}<p class="muted">${esc(v.description||'Keine Beschreibung.')}</p></div><div class="card-actions virtual-actions">${v.network_type==='vpn'?`<button class="button small primary" data-action="vpn-interface-add" data-network="${v.id}">Router verbinden</button>`:''}<button class="button small secondary" data-action="virtual-network-edit" data-id="${v.id}">Bearbeiten</button><button class="button small danger" data-delete="virtual-networks" data-id="${v.id}">Löschen</button></div></article>`;}).join('')||'<div class="panel empty">Noch keine virtuellen Netze angelegt.</div>'}</div></section>`;}
function renderIpam() {
  const spaces=state.data['address-spaces'];const space=spaces.find(s=>Number(s.id)===Number(state.selectedSpace));const network=state.data.networks.find(n=>Number(n.id)===Number(state.selectedNetwork));const children=network?state.data.networks.filter(n=>Number(n.parent_id)===Number(network.id)):[];
  app.innerHTML=pageHead('IPv4-Planungsraum','Offene Adressräume wachsen aus einer Start-IP; Gruppen sind optional, Subnetzgrößen werden berechnet.',`<label class="auto-replan-toggle" title="Browserlokale Einstellung; Adressraum-/Site-Verschiebungen, Rollbacks und Grenzwarnungen bleiben manuell."><input type="checkbox" id="auto-replan" ${state.autoReplan?'checked':''}><span>Replans automatisch übernehmen</span></label><button class="button secondary" data-action="site-add">Site anlegen</button><button class="button primary" data-action="space-add">Adressraum anlegen</button>`)+`<div class="ipam-filter"><label>Site <select id="ipam-site">${optionList(state.data.sites,state.selectedSite,'Alle Sites')}</select></label>${state.selectedSite?'<button class="button small secondary" data-action="site-filter-clear">Filter aufheben</button>':''}</div>${spaces.length?`<div class="space-tabs">${spaces.map(s=>`<button class="space-tab ${Number(s.id)===Number(state.selectedSpace)?'active':''}" data-action="space-select" data-id="${s.id}"><strong>${esc(s.name)}</strong><span>ab ${esc(s.start_ip)} · VRF ${esc(s.routing_domain||'default')}</span></button>`).join('')}</div>`:''}${space?`<div class="dynamic-space-summary"><div><span>Start-IP</span><strong class="mono">${esc(space.start_ip)}</strong></div><div><span>Dynamisches Gesamt-CIDR</span><strong class="mono">${esc(space.effective_cidr||'noch unbelegt')}</strong></div><div><span>Aktuelles Ende</span><strong class="mono">${esc(space.effective_end||'offen')}</strong></div><div><span>Routing-Domäne</span><strong>${esc(space.routing_domain||'default')}</strong></div>${space.leading_buffer?`<small>${number(space.leading_buffer)} Adressen liegen als ausrichtungsbedingter Puffer vor der Start-IP.</small>`:''}</div>`:''}<div class="planner-layout">
    <aside class="panel network-tree"><div class="panel-head"><div><h3>${space?esc(space.name):'Adressräume'}</h3>${space?`<span class="mono muted">dynamisch ab ${esc(space.start_ip)}</span>`:''}</div>${space?`<span class="actions"><button class="button small secondary" data-action="space-edit" data-id="${space.id}">✎</button><button class="button small danger" data-delete="address-spaces" data-id="${space.id}">×</button></span>`:''}</div>${space?`<div class="tree-actions"><button class="button small primary" data-action="network-plan" data-kind="container" data-root="1">Gruppe +</button><button class="button small secondary" data-action="network-plan" data-kind="leaf" data-root="1">Subnetz +</button></div><div class="network-tree-body">${networkBranch()||'<div class="empty">Noch keine Gruppen oder Subnetze angelegt.</div>'}</div>`:'<div class="empty">Lege zuerst einen offenen Adressraum an.</div>'}</aside>
    <section>${network?`<div class="panel"><div class="panel-head"><div><p class="eyebrow">${network.node_type==='leaf'?'SUBNETZ':'OPTIONALE GRUPPE'}</p><h3>${esc(network.name)}</h3><span class="mono muted">${esc(network.cidr)} · ${esc(network.site_name||'siteübergreifend')}</span></div><div class="actions"><button class="button small secondary" data-action="dynamic-network-edit" data-id="${network.id}">Bearbeiten</button>${network.node_type==='container'?`<button class="button small secondary" data-action="network-plan" data-kind="container">Gruppe +</button><button class="button small secondary" data-action="network-plan" data-kind="leaf">Subnetz +</button>`:''}<button class="button small danger" data-delete="networks" data-id="${network.id}">Löschen</button></div></div><div class="panel-body"><div class="capacity"><div><strong>${number(network.host_capacity)}</strong><span>${network.node_type==='leaf'?'Hostkapazität':'CIDR-Adressen'}</span></div><div><strong>${number(network.assigned_count)}</strong><span>Zugewiesen</span></div><div><strong>${number(network.free_count)}</strong><span>Frei</span></div><div><strong>${network.utilization}%</strong><span>Auslastung</span></div></div><div class="network-facts"><span>Gateway <b class="mono">${esc(network.gateway||'–')}</b></span><span>Planbedarf <b>${number(network.requested_hosts)} Hosts</b></span><span>Reserve <b>${network.reserve_percent}%</b></span></div></div>${children.length?`<div class="table-wrap"><table><thead><tr><th>Kind</th><th>Berechnetes CIDR</th><th>Kapazität</th></tr></thead><tbody>${children.map(c=>`<tr><td>${esc(c.name)}</td><td class="mono">${esc(c.cidr)}</td><td>${number(c.free_count)} frei</td></tr>`).join('')}</tbody></table></div>`:''}</div>`:`<div class="panel"><div class="empty">${space?'Start-IP gesetzt. Lege direkt ein Subnetz oder zunächst eine optionale Gruppe an.':'Noch kein Adressraum vorhanden.'}</div></div>`}</section>
    <aside>${renderPlannerPanel(network)}</aside></div>${renderVirtualNetworks()}`;
  if(space){const tree=document.querySelector('.network-tree-body');if(tree)tree.innerHTML=siteBranches()||'<div class="empty">Noch keine Site in diesem Adressraum.</div>';const actions=document.querySelector('.network-tree .tree-actions');if(actions){const count=state.selectedNetworks.size;actions.innerHTML=`<button class="button small primary" data-action="site-add" data-space="${space.id}">Site +</button>${count?`<span class="selection-count">${count} gewählt</span><button class="button small secondary" data-action="network-wrap">Zusammenfassen</button><button class="button small secondary" data-action="network-move">Verschieben</button><button class="button small secondary" data-action="network-selection-clear">×</button>`:''}`;}}
  if(network){const role=networkRole(network),eyebrow=document.querySelector('.planner-layout section .eyebrow');if(eyebrow)eyebrow.textContent=networkRoleLabel(network).toUpperCase();const detailActions=document.querySelector('.planner-layout section .panel-head .actions');if(detailActions&&role==='subnet')detailActions.querySelector('[data-action="dynamic-network-edit"]')?.insertAdjacentHTML('afterend',`<button class="button small secondary" data-action="network-plan" data-kind="container">Untergruppe +</button><button class="button small secondary" data-action="network-plan" data-kind="leaf">Subnetz +</button>`);if(detailActions&&role==='group')detailActions.querySelector('[data-delete]')?.insertAdjacentHTML('beforebegin',`<button class="button small secondary" data-action="network-convert-role" data-role="aggregate" data-id="${network.id}">In Supernetz umwandeln</button>`);if(detailActions&&role==='aggregate')detailActions.querySelector('[data-delete]')?.insertAdjacentHTML('beforebegin',`<button class="button small primary" data-action="network-activate-l3" data-id="${network.id}">Als gemeinsames L3-Netz</button><button class="button small secondary" data-action="network-convert-role" data-role="group" data-id="${network.id}">In Gruppe umwandeln</button><button class="button small secondary" data-action="network-convert-leaf" data-id="${network.id}">Als Blatt verwenden</button>`);if(detailActions&&role==='l3_subnet')detailActions.querySelector('[data-delete]')?.insertAdjacentHTML('beforebegin',`<button class="button small primary" data-action="pool-add" data-id="${network.id}">Pool +</button><button class="button small secondary" data-action="network-deactivate-l3" data-id="${network.id}">L3-Modus aus</button>`);}
}

function hostSearchText(h){return[h.name,h.hostname,h.fqdn,h.site_name,h.type,h.status,h.description,...h.aliases.map(a=>a.fqdn),...h.interfaces.map(i=>(i.ips||[i.ip]).join(' ')+' '+i.dns_name)].join(' ').toLowerCase();}
function filteredHosts(){const global=state.query.toLowerCase(),q=state.hostFilters.q.toLowerCase();return state.data.hosts.filter(h=>(!global||hostSearchText(h).includes(global))&&(!q||hostSearchText(h).includes(q))&&(!state.hostFilters.site||String(h.site_id)===String(state.hostFilters.site))&&(!state.hostFilters.type||h.type===state.hostFilters.type)&&(!state.hostFilters.status||h.status===state.hostFilters.status));}
function hostFilterBar(count){const types=['server','vm','network','client','appliance','other'],statuses=['planned','active','degraded','inactive'];return`<div class="host-filterbar"><label>Filter <input id="host-filter-text" value="${esc(state.hostFilters.q)}" placeholder="Name, FQDN oder IP"></label><label>Site <select id="host-filter-site">${optionList(state.data.sites.map(site=>({value:site.id,label:site.name})),state.hostFilters.site,'Alle Sites')}</select></label><label>Typ <select id="host-filter-type">${optionList(types.map(type=>({value:type,label:type})),state.hostFilters.type,'Alle Typen')}</select></label><label>Status <select id="host-filter-status">${optionList(statuses.map(status=>({value:status,label:labels[status]})),state.hostFilters.status,'Alle Status')}</select></label><span class="host-filter-count">${number(count)} von ${number(state.data.hosts.length)} Hosts</span><button class="button small secondary" data-action="host-filter-reset">Zurücksetzen</button></div>`;}
function hostSpreadsheetRow(h,index){const ips=h.interfaces.flatMap(i=>i.ips||[i.ip]);return`<tr data-host-row="${h.id}"><td class="sheet-row-number">${index+1}</td><td><input data-host-field="name" value="${esc(h.name)}" required></td><td><input class="mono" data-host-field="hostname" value="${esc(h.hostname)}" required><small class="sheet-hint mono">${esc(h.fqdn)}</small></td><td><select data-host-field="site_id" required>${optionList(state.data.sites.map(site=>({value:site.id,label:site.name})),h.site_id,'Site wählen')}</select></td><td><select data-host-field="type">${optionList(['server','vm','network','client','appliance','other'].map(type=>({value:type,label:type})),h.type,'Typ')}</select></td><td><select data-host-field="status">${optionList(['planned','active','degraded','inactive'].map(status=>({value:status,label:labels[status]})),h.status,'Status')}</select></td><td class="mono sheet-ips">${ips.map(esc).join('<br>')||'–'}<small class="sheet-hint">${h.interfaces.map(i=>i.name).map(esc).join(', ')||'Keine Interfaces'}</small></td><td><input data-host-field="description" value="${esc(h.description)}" placeholder="Beschreibung"></td><td class="sheet-actions"><button class="sheet-command save" data-action="host-row-save" data-id="${h.id}" title="Zeile speichern">✓</button><button class="sheet-command" data-action="interface-add" data-id="${h.id}" title="Interface anlegen">IP +</button><button class="sheet-command" data-action="host-edit" data-id="${h.id}" title="Alle Details bearbeiten">•••</button></td></tr>`;}
function newHostSpreadsheetRow(){if(!state.data.sites.length)return`<tr class="sheet-new-row"><td class="sheet-row-number">+</td><td colspan="8">Lege zuerst eine Site an, bevor du Hosts in der Tabelle erfasst.</td></tr>`;const siteId=state.hostFilters.site||state.data.sites[0].id;return`<tr class="sheet-new-row" data-host-new-row><td class="sheet-row-number">+</td><td><input data-host-field="name" placeholder="Neuer Host" required></td><td><input class="mono" data-host-field="hostname" placeholder="hostname oder fqdn." required><small class="sheet-hint">Neue Host-Zeile</small></td><td><select data-host-field="site_id" required>${optionList(state.data.sites.map(site=>({value:site.id,label:site.name})),siteId,'Site wählen')}</select></td><td><select data-host-field="type">${optionList(['server','vm','network','client','appliance','other'].map(type=>({value:type,label:type})),'server','Typ')}</select></td><td><select data-host-field="status">${optionList(['planned','active','degraded','inactive'].map(status=>({value:status,label:labels[status]})),'planned','Status')}</select></td><td class="sheet-ips muted">Nach dem Anlegen über „IP +“</td><td><input data-host-field="description" placeholder="Optionale Beschreibung"></td><td class="sheet-actions"><button class="sheet-command create" data-action="host-row-create" title="Neuen Host anlegen">＋ Anlegen</button></td></tr>`;}
function renderHosts() {
  const hosts=filteredHosts(),viewActions=`<div class="host-view-switch"><button class="button secondary ${state.hostView==='cards'?'active':''}" data-action="host-view-cards">Kacheln</button><button class="button secondary ${state.hostView==='table'?'active':''}" data-action="host-view-table">Tabelle</button></div><button class="button primary" data-action="host-add">Host anlegen</button>`;
  const cards=`<div class="host-grid">${hosts.map(h=>{const docker=(state.data['virtual-networks']||[]).filter(v=>v.network_type==='docker_bridge'&&Number(v.owner_host_id)===Number(h.id));return`<article class="panel host-card"><div class="host-top"><div><h3>${esc(h.name)}</h3><div class="host-fqdn mono">${esc(h.fqdn)}</div><div class="host-meta">${esc(h.site_name)} · ${esc(h.type)}</div></div>${badge(h.status)}</div>${h.aliases.length?`<div class="alias-list">${h.aliases.map(a=>`<span title="${esc(a.fqdn)}">${esc(a.input_name)}</span>`).join('')}</div>`:''}<div class="ip-list">${h.interfaces.length?h.interfaces.map(i=>`<div class="ip-item"><span>${esc(i.name)} · <strong class="mono">${(i.ips||[i.ip]).map(esc).join(', ')}</strong>${i.dns_name?`<small class="interface-dns">${esc(i.dns_name)}</small>`:''}</span><span><button class="button small secondary" data-action="interface-edit" data-id="${i.id}">✎</button><button class="button small danger" data-delete="interfaces" data-id="${i.id}">×</button></span></div>`).join(''):'<span class="muted">Keine Interfaces</span>'}${docker.map(v=>`<div class="ip-item docker"><span>Docker · <strong>${esc(v.name)}</strong><small class="interface-dns">${esc(v.cidr)} · GW ${esc(v.gateway)}</small></span><button class="button small secondary" data-action="virtual-network-edit" data-id="${v.id}">✎</button></div>`).join('')}</div><div class="host-meta">${h.service_count} Dienste · ${esc(h.description)}</div><div class="card-actions"><button class="button small secondary" data-action="host-edit" data-id="${h.id}">Bearbeiten</button><button class="button small secondary" data-action="interface-add" data-id="${h.id}">Interface +</button><button class="button small secondary" data-action="docker-network-add" data-id="${h.id}">Docker +</button><button class="button small secondary" data-action="service-add" data-id="${h.id}">Dienst +</button><button class="button small danger" data-delete="hosts" data-id="${h.id}">Löschen</button></div></article>`;}).join('')||'<div class="panel empty">Keine passenden Hosts gefunden.</div>'}</div>`;
  const table=`<div class="panel host-sheet"><div class="table-wrap"><table><thead><tr><th class="sheet-row-number">#</th><th>Name</th><th>Hostname / FQDN</th><th>Site</th><th>Typ</th><th>Status</th><th>IP-Adressen</th><th>Beschreibung</th><th>Aktionen</th></tr></thead><tbody>${newHostSpreadsheetRow()}${hosts.map(hostSpreadsheetRow).join('')}${hosts.length?'':'<tr class="sheet-empty"><td class="sheet-row-number">–</td><td colspan="8">Keine passenden bestehenden Hosts gefunden.</td></tr>'}</tbody></table></div><div class="sheet-footer">Tab: nächste Zelle · Strg/Cmd + Enter: aktuelle Zeile anlegen oder speichern · Gelb markierte Zeilen enthalten ungespeicherte Änderungen</div></div>`;
  app.innerHTML=pageHead('Hosts','Physische Geräte, virtuelle Systeme und ihre Netzwerkinterfaces.',viewActions)+hostFilterBar(hosts.length)+(state.hostView==='table'?table:cards);
}
function portLabel(s){if(!s.port_start)return '–';return s.port_end&&s.port_end!==s.port_start?`${s.port_start}–${s.port_end}`:s.port_start;}
function renderRouters(){const routers=state.data.routers;if(!state.selectedRouter&&routers[0])state.selectedRouter=Number(routers[0].id);const router=routers.find(r=>Number(r.id)===Number(state.selectedRouter)),interfaces=router?state.data.interfaces.filter(i=>Number(i.host_id)===Number(router.id)):[],vpn=router?(state.data['vpn-interfaces']||[]).filter(i=>Number(i.router_id)===Number(router.id)):[];app.innerHTML=pageHead('Router','Gateways, siteübergreifende Interfaces, VPN-Transitnetze und statische IPv4-Routen planen.',`<button class="button primary" data-action="router-add">Router anlegen</button>`)+`<div class="router-layout"><aside class="panel router-list">${routers.map(r=>{const vpnCount=(state.data['vpn-interfaces']||[]).filter(i=>Number(i.router_id)===Number(r.id)).length;return`<button class="router-list-item ${Number(r.id)===Number(state.selectedRouter)?'active':''}" data-action="router-select" data-id="${r.id}"><strong>${esc(r.name)}</strong><small>${esc(r.fqdn)} · ${Number(r.interface_count)+vpnCount} Interfaces</small></button>`;}).join('')||'<div class="empty">Noch keine Router angelegt.</div>'}</aside><section>${router?`<div class="panel"><div class="panel-head"><div><p class="eyebrow">ROUTER</p><h3>${esc(router.name)}</h3><span class="mono muted">${esc(router.fqdn)} · Heimat-Site ${esc(router.site_name)}</span></div><div class="actions"><button class="button small secondary" data-action="docker-network-add" data-id="${router.id}">Docker +</button><button class="button small secondary" data-action="router-edit" data-id="${router.id}">Bearbeiten</button><button class="button small danger" data-delete="routers" data-id="${router.id}">Löschen</button></div></div><div class="panel-body"><div class="capacity"><div><strong>${interfaces.length+vpn.length}</strong><span>Interfaces</span></div><div><strong>${vpn.length}</strong><span>VPN-Tunnel</span></div><div><strong>${router.gateway_count}</strong><span>Gateways</span></div><div><strong>${badge(router.status)}</strong><span>Status</span></div></div></div></div><div class="panel router-section"><div class="panel-head"><h3>Interfaces und Gateways</h3><button class="button small primary" data-action="router-interface-add" data-id="${router.id}">Interface +</button></div><div class="table-wrap"><table><thead><tr><th>Interface</th><th>Netz</th><th>IP-Adresse</th><th></th></tr></thead><tbody>${interfaces.map(i=>`<tr><td><strong>${esc(i.name)}</strong></td><td>${esc(i.subnet_cidr)}</td><td class="mono">${(i.ips||[i.ip]).map(esc).join(', ')}</td><td><button class="button small secondary" data-action="interface-edit" data-id="${i.id}">Bearbeiten</button></td></tr>`).join('')||'<tr><td colspan="4">Noch kein LAN-Interface.</td></tr>'}</tbody></table></div></div><div class="panel router-section"><div class="panel-head"><h3>VPN-Interfaces</h3><button class="button small primary" data-action="vpn-interface-add" data-router="${router.id}">VPN beitreten</button></div><div class="table-wrap"><table><thead><tr><th>Interface</th><th>VPN-Netz</th><th>Tunnel-IP</th><th></th></tr></thead><tbody>${vpn.map(i=>`<tr><td><strong>${esc(i.name)}</strong></td><td>${esc(i.network_name)} · <span class="mono">${esc(i.cidr)}</span></td><td class="mono">${(i.ips||[i.ip]).map(esc).join(', ')}</td><td><button class="button small secondary" data-action="vpn-interface-edit" data-id="${i.id}">Bearbeiten</button> <button class="button small danger" data-delete="vpn-interfaces" data-id="${i.id}">×</button></td></tr>`).join('')||'<tr><td colspan="4">Noch mit keinem globalen VPN verbunden.</td></tr>'}</tbody></table></div></div><div class="panel router-section"><div class="panel-head"><h3>Routingtabelle</h3><div class="actions"><button class="button small secondary" data-action="route-suggest" data-id="${router.id}">Vorschläge</button><button class="button small primary" data-action="route-add" data-id="${router.id}">Route +</button></div></div><div class="table-wrap"><table><thead><tr><th>Typ</th><th>Ziel</th><th>Next Hop</th><th>Interface</th><th>Metrik</th><th></th></tr></thead><tbody>${router.routes.map(r=>`<tr><td>${r.route_type==='connected'?'Verbunden':'Statisch'}</td><td class="mono">${esc(r.destination_cidr)}</td><td class="mono">${esc(r.next_hop)}</td><td>${esc(r.interface_name)}</td><td>${r.metric}</td><td>${r.route_type==='static'?`<button class="button small secondary" data-action="route-edit" data-id="${r.id}">Bearbeiten</button> <button class="button small danger" data-delete="static-routes" data-id="${r.id}">×</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6">Noch keine verbundenen Netze oder Routen.</td></tr>'}</tbody></table></div></div>`:'<div class="panel empty">Wähle oder erstelle einen Router.</div>'}</section></div>`;}

async function showRouteSuggestions(routerId){const rows=await api(`planner/route-suggestions/${routerId}`);document.querySelector('#modal-kicker').textContent='ROUTENVORSCHLÄGE';document.querySelector('#modal-title').textContent='Erreichbare entfernte Netze';document.querySelector('#modal-body').innerHTML=rows.length?rows.map((r,i)=>`<div class="route-suggestion"><strong>${esc(r.destination_name)} · <span class="mono">${esc(r.destination_cidr)}</span></strong><span>via ${esc(r.next_hop)} · Metrik ${r.metric}</span><button type="button" class="button small primary" data-action="route-accept" data-index="${i}">Übernehmen</button></div>`).join(''):'<div class="empty">Keine neuen erreichbaren Netze gefunden. Router benötigen ein gemeinsames Transitnetz.</div>';document.querySelector('#modal-submit').textContent='Schließen';modalForm.onsubmit=e=>{e.preventDefault();modal.close();};modal.dataset.suggestions=JSON.stringify(rows);modal.showModal();}

function renderServices() {
  const q=state.query.toLowerCase();const services=state.data.services.filter(s=>!q||[s.name,s.host_name,s.url,s.protocol,s.environment].join(' ').toLowerCase().includes(q));
  app.innerHTML=pageHead('Dienste','Technische Services, Ports, URLs und Betriebszustände.',`<button class="button primary" data-action="service-add">Dienst anlegen</button>`)+`<div class="panel">${services.length?`<div class="table-wrap"><table><thead><tr><th>Dienst</th><th>Host</th><th>Endpoint</th><th>Umgebung</th><th>Status</th><th></th></tr></thead><tbody>${services.map(s=>`<tr><td><strong>${esc(s.name)}</strong><br><span class="muted">${esc(s.description)}</span></td><td>${esc(s.host_name)}</td><td class="mono">${esc(s.protocol.toUpperCase())} ${esc(portLabel(s))}<br><span class="muted">${esc(s.url)}</span></td><td>${esc(labels[s.environment]||s.environment)}</td><td>${badge(s.status)}</td><td><div class="actions"><button class="button small secondary" data-action="service-edit" data-id="${s.id}">Bearbeiten</button><button class="button small danger" data-delete="services" data-id="${s.id}">Löschen</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Noch keine Dienste angelegt.</div>'}</div>`;
}
function renderRelations() {
  const q=state.query.toLowerCase();const rows=state.data.relations.filter(r=>!q||[r.source_name,r.target_name,r.label,r.type].join(' ').toLowerCase().includes(q));
  app.innerHTML=pageHead('Beziehungen','Gerichtete und ungerichtete Abhängigkeiten zwischen Infrastruktur-Objekten.',`<button class="button primary" data-action="relation-add">Beziehung anlegen</button>`)+`<div class="panel">${rows.length?`<div class="table-wrap"><table><thead><tr><th>Quelle</th><th>Beziehung</th><th>Ziel</th><th>Notiz</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="badge">${esc(labels[r.source_kind])}</span> <strong>${esc(r.source_name)}</strong></td><td><strong>${esc(r.label||labels[r.type]||r.type)}</strong><br><span class="muted">${esc(labels[r.type]||r.type)}</span></td><td><span class="badge">${esc(labels[r.target_kind])}</span> <strong>${esc(r.target_name)}</strong></td><td>${esc(r.notes)}</td><td><div class="actions"><button class="button small secondary" data-action="relation-edit" data-id="${r.id}">Bearbeiten</button><button class="button small danger" data-delete="relations" data-id="${r.id}">Löschen</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Noch keine manuellen Beziehungen angelegt.</div>'}</div>`;
}

function renderTools(){
  app.innerHTML=pageHead('IPv4-Tools','Adressbereiche und CIDRs analysieren, dimensionieren, zusammenfassen und aufteilen.')+`<div class="calculator-grid">
    <section class="panel calculator-card"><div class="panel-head"><div><p class="eyebrow">CIDR ANALYSIEREN</p><h3>Netzdetails</h3></div></div><form class="calculator-form" data-calculator-mode="analyze"><label>IPv4-Adresse mit Präfix<input name="cidr" value="192.168.10.25/24" placeholder="192.168.10.25/24" required></label><button class="button primary" type="submit">Analysieren</button></form><div class="calculator-result" id="calculator-result-analyze"></div></section>
    <section class="panel calculator-card"><div class="panel-head"><div><p class="eyebrow">HOSTBEDARF</p><h3>Passenden Präfix berechnen</h3></div></div><form class="calculator-form two-fields" data-calculator-mode="hosts"><label>Benötigte Hosts<input name="hosts" type="number" min="1" value="100" required></label><label>Reserve in Prozent<input name="reserve_percent" type="number" min="0" max="500" value="20" required></label><button class="button primary" type="submit">Dimensionieren</button></form><div class="calculator-result" id="calculator-result-hosts"></div></section>
    <section class="panel calculator-card"><div class="panel-head"><div><p class="eyebrow">ADRESSBEREICH</p><h3>Bereich in CIDRs umrechnen</h3></div></div><form class="calculator-form two-fields" data-calculator-mode="range"><label>Start-IP<input name="start_ip" value="192.168.1.5" required></label><label>End-IP<input name="end_ip" value="192.168.1.14" required></label><button class="button primary" type="submit">Bereich berechnen</button></form><div class="calculator-result" id="calculator-result-range"></div></section>
    <section class="panel calculator-card"><div class="panel-head"><div><p class="eyebrow">SUBNETTING</p><h3>CIDR aufteilen</h3></div></div><form class="calculator-form two-fields" data-calculator-mode="split"><label>Ausgangs-CIDR<input name="cidr" value="10.0.0.0/24" required></label><label>Zielpräfix<input name="target_prefix" type="number" min="1" max="32" value="26" required></label><button class="button primary" type="submit">Aufteilen</button></form><div class="calculator-result" id="calculator-result-split"></div></section>
  </div>`;
  Object.entries(state.calculatorResults).forEach(([mode,result])=>renderCalculatorResult(mode,result));
}
function calculatorFact(label,value){return`<div class="calculator-fact"><span>${esc(label)}</span><strong class="mono">${esc(value)}</strong><button type="button" class="copy-mini" data-copy-value="${esc(value)}" title="Wert kopieren">⧉</button></div>`;}
function calculatorCopyText(mode){const r=state.calculatorResults[mode];if(!r)return'';if(mode==='range')return r.exact_cidrs.join('\n');if(mode==='split')return r.children.map(child=>child.cidr).join('\n');if(mode==='hosts')return `${r.prefix_label} · ${r.planned_hosts} geplante Hosts · ${r.usable} nutzbar`;return [`CIDR: ${r.cidr}`,`Netzwerk: ${r.network}`,`Broadcast: ${r.broadcast}`,`Netzmaske: ${r.netmask}`,`Wildcard: ${r.wildcard}`,`Nutzbar: ${r.first_usable} – ${r.last_usable}`].join('\n');}
function renderCalculatorResult(mode,result){
  state.calculatorResults[mode]=result;const target=document.querySelector(`#calculator-result-${mode}`);if(!target)return;
  if(mode==='analyze')target.innerHTML=`${result.normalized?`<p class="calculator-note">Die eingegebene Hostadresse liegt in <strong class="mono">${esc(result.cidr)}</strong>.</p>`:''}<div class="calculator-facts">${calculatorFact('CIDR',result.cidr)}${calculatorFact('Netzwerk',result.network)}${calculatorFact('Broadcast',result.broadcast)}${calculatorFact('Netzmaske',result.netmask)}${calculatorFact('Wildcard',result.wildcard)}${calculatorFact('Erste nutzbare IP',result.first_usable)}${calculatorFact('Letzte nutzbare IP',result.last_usable)}${calculatorFact('Adressen / nutzbar',`${number(result.size)} / ${number(result.usable)}`)}</div><button type="button" class="button small secondary" data-copy-mode="analyze">Ergebnis kopieren</button>`;
  if(mode==='hosts')target.innerHTML=`<div class="calculator-highlight"><span>Empfohlener Präfix</span><strong class="mono">${esc(result.prefix_label)}</strong></div><div class="calculator-facts">${calculatorFact('Bedarf mit Reserve',number(result.planned_hosts))}${calculatorFact('Gesamtadressen',number(result.size))}${calculatorFact('Nutzbare Adressen',number(result.usable))}${calculatorFact('Verbleibend',number(result.remaining))}</div><button type="button" class="button small secondary" data-copy-mode="hosts">Ergebnis kopieren</button>`;
  if(mode==='range')target.innerHTML=`<div class="calculator-facts">${calculatorFact('Kleinstes Supernetz',result.cover_cidr)}${calculatorFact('Adressen im Bereich',number(result.size))}${calculatorFact('Zusätzliche Adressen im Supernetz',number(result.cover_extra))}${calculatorFact('Exakte CIDR-Anzahl',number(result.exact_cidrs.length))}</div><pre class="cidr-output">${esc(result.exact_cidrs.join('\n'))}</pre><button type="button" class="button small secondary" data-copy-mode="range">CIDR-Liste kopieren</button>`;
  if(mode==='split')target.innerHTML=`<div class="calculator-facts">${calculatorFact('Ausgangsnetz',result.source_cidr)}${calculatorFact('Teilnetze',number(result.count))}${calculatorFact('Zielpräfix','/'+result.target_prefix)}</div><pre class="cidr-output">${esc(result.children.map(child=>`${child.cidr} · ${child.network}–${child.broadcast} · ${number(child.usable)} nutzbar`).join('\n'))}</pre><button type="button" class="button small secondary" data-copy-mode="split">CIDR-Liste kopieren</button>`;
}
async function copyText(value){if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(value);else{const area=document.createElement('textarea');area.value=value;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();document.execCommand('copy');area.remove();}notify('In die Zwischenablage kopiert.');}

function placeUnpositionedSiteMembers(site,members,saved,baseX,rowY){
  const positioned=[],pending=[];
  members.forEach(node=>{if(saved.has(node.id)){Object.assign(node,saved.get(node.id));positioned.push(node);}else pending.push(node);});
  if(!pending.length)return;
  const siteAnchor=saved.get(site.id),startX=positioned.length?Math.min(...positioned.map(node=>node.x)):(siteAnchor?.x??baseX),startY=positioned.length?Math.min(...positioned.map(node=>node.y)):(siteAnchor?siteAnchor.y+70:rowY),occupied=[...positioned];
  pending.forEach(node=>{const siblings=node.parent_id?occupied.filter(other=>Number(other.parent_id)===Number(node.parent_id)):[],parent=saved.get(Number(node.parent_id)),localX=siblings.length?Math.min(...siblings.map(other=>other.x)):(parent?.x??startX),localY=siblings.length?Math.min(...siblings.map(other=>other.y)):(parent?parent.y+65:startY);let placed=false;for(let slot=0;slot<500&&!placed;slot++){const candidate={x:localX+(slot%4)*165,y:localY+Math.floor(slot/4)*72};if(occupied.some(other=>Math.abs(other.x-candidate.x)<145&&Math.abs(other.y-candidate.y)<62))continue;node.x=candidate.x;node.y=candidate.y;occupied.push(node);placed=true;}if(!placed){node.x=localX;node.y=localY+occupied.length*72;occupied.push(node);}});
}
function layoutTopology(topology,saved=new Map(),force=false){
  const sites=topology.nodes.filter(n=>n.kind==='site'),globals=topology.nodes.filter(n=>n.kind!=='site'&&!n.site_id);
  globals.forEach((node,index)=>{
    if(!force&&saved.has(node.id)){Object.assign(node,saved.get(node.id));return;}
    node.x=120+(index%7)*190;node.y=75+Math.floor(index/7)*85;
  });
  const globalBottom=globals.length?Math.max(...globals.map(node=>node.y))+130:120;
  let rowY=globalBottom;
  for(let offset=0;offset<sites.length;offset+=2){
    let rowBottom=rowY+180;
    sites.slice(offset,offset+2).forEach((site,column)=>{
      const baseX=120+column*820,counts={},members=topology.nodes.filter(n=>n.kind!=='site'&&Number(n.site_id)===Number(site.id));site.x=baseX+90;site.y=rowY-45;
      if(!members.length&&!force&&saved.has(site.id))Object.assign(site,saved.get(site.id));
      if(!force&&(saved.has(site.id)||members.some(node=>saved.has(node.id))))placeUnpositionedSiteMembers(site,members,saved,baseX,rowY);
      else members.forEach(node=>{if(!force&&saved.has(node.id)){Object.assign(node,saved.get(node.id));return;}const lane={block:0,subnet:1,host:2,service:3,router:4}[node.kind]??1,slot=counts[lane]||0;counts[lane]=slot+1;node.x=baseX+lane*190;node.y=rowY+slot*78;});
      const bounds=siteRegionBounds(topology,site);rowBottom=Math.max(rowBottom,bounds.y+bounds.height);
    });
    rowY=rowBottom+50;
  }
}
