function keepRoutersOutsideGroups(topology){const slots=new Map(),routers=topology.nodes.filter(node=>node.kind==='router');routers.forEach(router=>{const groups=topologyGroups(topology).filter(group=>Number(group.site_id)===Number(router.site_id)&&group.region),inside=groups.some(group=>router.x>group.region.x-70&&router.x<group.region.x+group.region.width+70&&router.y>group.region.y-35&&router.y<group.region.y+group.region.height+35);if(!inside)return;const slot=slots.get(router.site_id)||0;slots.set(router.site_id,slot+1);router.x=Math.max(...groups.map(group=>group.region.x+group.region.width))+105;router.y=Math.min(...groups.map(group=>group.region.y))+70+slot*72;});}
