function topologyHostTableSource(topology,sourceId){return topology.nodes.find(node=>Number(node.id)===Number(sourceId));}
function buildTopologyHostTables(topology){topology.nodes.forEach(node=>{delete node.host_table_id;delete node.host_table_source;});const firstNetwork=new Map(),groups=new Map();topology.edges.forEach(edge=>{const host=topology.nodes.find(node=>Number(node.id)===Number(edge.target)&&node.kind==='host');if(edge.type!=='assigned'||!host||firstNetwork.has(Number(host.id)))return;const key=Number(edge.source);firstNetwork.set(Number(host.id),key);const group=groups.get(key)||[];group.push(host);groups.set(key,group);});const tables=[];for(const[sourceId,hosts]of groups){const source=topologyHostTableSource(topology,sourceId);if(!source)continue;hosts.sort((a,b)=>String(a.name).localeCompare(String(b.name),'de'));const width=250,headerHeight=0,rowHeight=24,table={id:`host-table-${sourceId}`,source_id:sourceId,site_id:hosts[0].site_id,source,hosts,width,headerHeight,rowHeight,x:source.x-width/2,y:source.y+25};source.host_table_source=true;hosts.forEach(host=>host.host_table_id=table.id);table.height=hosts.length*rowHeight;tables.push(table);}tables.sort((a,b)=>Number(a.site_id)-Number(b.site_id)||a.source.y-b.source.y);const cursors=new Map();tables.forEach(table=>{const bucket=`${table.site_id}:${Math.round(table.source.x/280)}`,top=table.source.y-25,cursor=cursors.get(bucket);if(cursor!==undefined&&top<cursor){const dy=cursor-top;table.source.y+=dy;table.y+=dy;}cursors.set(bucket,table.y+table.height+14);});topology.hostTables=tables;syncTopologyHostTables(topology);}
