function wireTopologyDrag(){
  const svg=document.querySelector('#topology-svg');let active=null,activeElement=null,tapTarget=null,start=null,lastPoint=null,panOrigin=null,panning=false,moved=false,longPress=null;
  const point=e=>{const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());},targetFor=element=>{if(!element)return null;const id=Number(element.dataset.node||element.dataset.siteRegion||element.dataset.groupRegion);return state.topology.nodes.find(n=>n.id===id);},clearLong=()=>{if(longPress)clearTimeout(longPress);longPress=null;},finish=()=>{activeElement?.classList.remove('dragging');svg.classList.remove('panning');active=null;activeElement=null;tapTarget=null;start=null;lastPoint=null;panOrigin=null;panning=false;};
  const autoPan=e=>{const rect=svg.getBoundingClientRect(),view=state.topologyViewport,edge=42;if(!view)return;const stepX=Math.max(12,view.width*.018),stepY=Math.max(10,view.height*.018);let dx=0,dy=0;if(e.clientX<rect.left+edge)dx=-stepX;else if(e.clientX>rect.right-edge)dx=stepX;if(e.clientY<rect.top+edge)dy=-stepY;else if(e.clientY>rect.bottom-edge)dy=stepY;if(dx||dy)panTopology(dx,dy);};
  svg.addEventListener('contextmenu',e=>{e.preventDefault();clearLong();const element=e.target.closest('.node,[data-site-region],[data-group-region]'),edgeEl=e.target.closest('[data-edge]');if(element)return openNodeContext(targetFor(element),e.clientX,e.clientY);if(edgeEl)return openEdgeContext(state.topology.edges[Number(edgeEl.dataset.edge)],e.clientX,e.clientY);openCanvasContext(e.clientX,e.clientY);});
  svg.addEventListener('keydown',e=>{const element=e.target.closest('.node,[data-site-region],[data-group-region]');if((e.key==='ContextMenu'||(e.shiftKey&&e.key==='F10'))&&element){e.preventDefault();const box=element.getBoundingClientRect();openNodeContext(targetFor(element),box.left+box.width/2,box.top+Math.min(35,box.height/2));}});
  svg.addEventListener('pointerdown',e=>{closeContextMenu();const element=e.target.closest('.node,[data-site-region],[data-group-region]'),edgeElement=e.target.closest('[data-edge]');tapTarget=targetFor(element);start={x:e.clientX,y:e.clientY};lastPoint=point(e);moved=false;const canvasPan=e.button===1||(!element&&!edgeElement&&e.button===0);if(canvasPan){e.preventDefault();panning=true;panOrigin={...state.topologyViewport};svg.classList.add('panning');svg.setPointerCapture(e.pointerId);return;}if(e.pointerType==='touch')longPress=setTimeout(()=>{if(element)openNodeContext(tapTarget,e.clientX,e.clientY);else openCanvasContext(e.clientX,e.clientY);active=null;},600);if(!element||e.button!==0)return;active=tapTarget;activeElement=element;element.setPointerCapture(e.pointerId);});
  svg.addEventListener('pointermove',e=>{if(start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>5){moved=true;clearLong();activeElement?.classList.add('dragging');}if(panning&&panOrigin&&moved){const scaleX=panOrigin.width/Math.max(1,svg.clientWidth),scaleY=panOrigin.height/Math.max(1,svg.clientHeight);state.topologyViewport={...panOrigin,x:panOrigin.x-(e.clientX-start.x)*scaleX,y:panOrigin.y-(e.clientY-start.y)*scaleY};applyTopologyViewport();return;}if(!active||!moved)return;autoPan(e);const p=point(e);if(active.kind==='site'){const bounds=active.region,members=state.topology.nodes.filter(node=>node.kind!=='site'&&Number(node.site_id)===Number(active.id));let dx=p.x-lastPoint.x,dy=p.y-lastPoint.y;dx=Math.max(5-bounds.x,Math.min(4900-bounds.x-bounds.width,dx));dy=Math.max(5-bounds.y,Math.min(4900-bounds.y-bounds.height,dy));active.x+=dx;active.y+=dy;members.forEach(node=>{node.x+=dx;node.y+=dy;});}else if(isTopologyContainer(active)){const bounds=active.region,members=groupContainedNodes(state.topology,active);let dx=p.x-lastPoint.x,dy=p.y-lastPoint.y;dx=Math.max(5-bounds.x,Math.min(4900-bounds.x-bounds.width,dx));dy=Math.max(5-bounds.y,Math.min(4900-bounds.y-bounds.height,dy));active.x+=dx;active.y+=dy;members.forEach(node=>{node.x+=dx;node.y+=dy;});}else if(active.kind==='host'&&active.host_table_id){const table=(state.topology.hostTables||[]).find(item=>item.id===active.host_table_id);let dx=p.x-lastPoint.x,dy=p.y-lastPoint.y;if(table){dx=Math.max(5-(table.source.x-62),Math.min(4900-table.x-table.width,dx));dy=Math.max(5-table.y,Math.min(4900-table.y-table.height,dy));table.source.x+=dx;table.source.y+=dy;}}else{active.x=Math.max(65,Math.min(4800,p.x));active.y=Math.max(55,Math.min(4800,p.y));}lastPoint=p;updateTopologyGeometry();});
  svg.addEventListener('pointerup',()=>{clearLong();if(tapTarget&&!moved&&state.relationSource)chooseRelationTarget(tapTarget);finish();});
  svg.addEventListener('pointercancel',()=>{clearLong();finish();});
  svg.addEventListener('wheel',e=>{e.preventDefault();zoomTopology(e.deltaY<0 ? 0.84 : 1.19,e.clientX,e.clientY);},{passive:false});
  svg.addEventListener('dblclick',e=>{if(!e.target.closest('.node,[data-site-region],[data-group-region],[data-edge]'))fitTopologyViewport();});
}

async function render(){
  const route=routeInfo(),view=route.view;state.view=['dashboard','sites','ipam','hosts','routers','services','topology','relations','tools'].includes(view)?view:'dashboard';
  document.body.classList.toggle('topology-mode',state.view==='topology');if(state.view!=='topology')document.body.classList.remove('topology-fullscreen');
  if(state.view==='topology')state.topologySite=route.params.get('site')||'';
  if(state.view==='ipam'){state.selectedSite=route.params.get('site')||'';if(state.selectedSite){const site=state.data.sites.find(s=>Number(s.id)===Number(state.selectedSite)),match=state.data.networks.find(n=>Number(n.site_id)===Number(state.selectedSite));if(site?.address_space_id)state.selectedSpace=Number(site.address_space_id);if(match)state.selectedNetwork=Number(match.id);else{state.selectedNetwork=null;state.analysis=null;}}}
  document.querySelectorAll('[data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===state.view));
  title.textContent={dashboard:'Übersicht',sites:'Sites',ipam:'Adressplanung',hosts:'Hosts',routers:'Router',services:'Dienste',topology:'Topologie',relations:'Beziehungen',tools:'Tools'}[state.view];
  closeContextMenu();if(state.view!=='topology')state.relationSource=null;
  if(state.view==='dashboard')renderDashboard();if(state.view==='sites')renderSites();if(state.view==='ipam'){renderIpam();if(state.selectedNetwork){state.analysis=await api(`planner/analyze/${state.selectedNetwork}`);if(state.view==='ipam')renderIpam();}}if(state.view==='hosts')renderHosts();if(state.view==='routers')renderRouters();if(state.view==='services')renderServices();if(state.view==='relations')renderRelations();if(state.view==='topology')await renderTopology();if(state.view==='tools')renderTools();
  requestAnimationFrame(()=>{document.querySelectorAll('.dynamic-space-summary>div').forEach(el=>{if(el.querySelector('span')?.textContent==='Routing-Domäne')el.remove();});document.querySelectorAll('.space-tab span,.site-space').forEach(el=>{el.innerHTML=el.innerHTML.replace(/\s*·\s*VRF\s+default/g,'').replace(/\s*·\s*default\s*$/g,'');});});
}

function interfaceNetworksForHost(hostId,currentNetworkId=0){const host=state.data.hosts.find(x=>Number(x.id)===Number(hostId));if(!host)return[];return state.data.networks.filter(x=>['subnet','l3_subnet'].includes(networkRole(x))&&(Number(x.site_id)===Number(host.site_id)||Number(x.id)===Number(currentNetworkId)));}
function interfacePoolsForHost(hostId,currentPoolId=0){const host=state.data.hosts.find(x=>Number(x.id)===Number(hostId));if(!host)return[];return state.data.networks.filter(x=>['static_pool','dhcp_pool'].includes(networkRole(x))&&(Number(x.site_id)===Number(host.site_id)||Number(x.id)===Number(currentPoolId)));}
