const dynamicNetworkFields=fields.network;
fields.network=(v={})=>{let result=dynamicNetworkFields(v);const role=networkRole(v);if(role==='aggregate')result=result.filter(field=>!['requested_hosts','vlan_id'].includes(field.name));if(role!=='group')result.splice(2,0,{name:'prefix',label:'Optionaler fester Präfix',value:v.manual_prefix===null||v.manual_prefix===undefined?'':`/${v.manual_prefix}`,placeholder:'/24',hint:role==='aggregate'?'Begrenzt den gesamten Kinderbereich; leer wächst das Supernetz dynamisch.':'Leer lassen: Der Planer bestimmt die Größe dynamisch und lässt das Subnetz mitwachsen.'});if(['subnet','aggregate'].includes(role))result.splice(3,0,{name:'start_ip',label:'Optionale feste Start-IP',value:v.manual_start_ip||'',placeholder:'172.20.1.64',hint:'Muss eine gültige Netzadresse für die berechnete oder manuell gewählte CIDR-Größe sein.'});return result;};
function fieldHtml(f){const id=`field-${f.name}`,listId=`${id}-suggestions`;let control;if(f.type==='select')control=`<select id="${id}" name="${f.name}" ${f.required?'required':''} ${f.disabled?'disabled':''}>${optionList(f.options||[],f.value)}</select>`;else if(f.type==='textarea')control=`<textarea id="${id}" name="${f.name}" ${f.required?'required':''} ${f.disabled?'disabled':''}>${esc(f.value)}</textarea>`;else control=`<input id="${id}" name="${f.name}" type="${f.type||'text'}" value="${esc(f.value)}" placeholder="${esc(f.placeholder)}" ${f.suggestions?.length?`list="${listId}"`:''} ${f.required?'required':''} ${f.disabled?'disabled':''}>${f.suggestions?.length?`<datalist id="${listId}">${f.suggestions.map(value=>`<option value="${esc(value)}"></option>`).join('')}</datalist>`:''}`;return `<div class="field ${f.wide?'wide':''}"><label for="${id}">${esc(f.label)}</label>${control}${f.hint?`<span class="hint">${esc(f.hint)}</span>`:''}</div>`;}
function primaryFqdnPreview(value,domain){const input=value.trim().toLowerCase();if(input.endsWith('.'))return input.slice(0,-1)||'–';return input&&domain?`${input}.${domain}`:'–';}
function openForm(kicker,heading,formFields,onSave){document.querySelector('#modal-kicker').textContent=kicker;document.querySelector('#modal-title').textContent=heading;const submit=document.querySelector('#modal-submit');submit.textContent='Speichern';const body=document.querySelector('#modal-body');body.innerHTML=formFields.map(fieldHtml).join('');const hostname=body.querySelector('[name="hostname"]'),site=body.querySelector('[name="site_id"]');if(hostname&&site){body.insertAdjacentHTML('beforeend','<div class="vlsm-preview" id="fqdn-preview">FQDN: –</div>');const preview=()=>{const domain=state.data.sites.find(x=>String(x.id)===site.value)?.domain_name||'';document.querySelector('#fqdn-preview').textContent=`FQDN: ${primaryFqdnPreview(hostname.value,domain)}`;};hostname.addEventListener('input',preview);site.addEventListener('change',preview);preview();}const interfaceHost=body.querySelector('[name="host_id"]'),interfaceNetwork=body.querySelector('[name="network_id"]'),interfacePool=body.querySelector('[name="pool_id"]');if(interfaceHost&&interfaceNetwork){interfaceHost.addEventListener('change',()=>{const networks=interfaceNetworksForHost(interfaceHost.value);interfaceNetwork.innerHTML=optionList(networks.map(x=>({value:x.id,label:siteOptionLabel(x,`${networkRoleLabel(x)} · ${x.name} · ${x.cidr}`)})),null);if(interfacePool){const pools=interfacePoolsForHost(interfaceHost.value);interfacePool.innerHTML=optionList(pools.map(x=>({value:x.id,label:siteOptionLabel(x,`${networkRoleLabel(x)} · ${x.name} · ${x.range_start}–${x.range_end}`)})),null);}});}modalForm.onsubmit=async e=>{e.preventDefault();const submit=document.querySelector('#modal-submit');submit.disabled=true;try{const values=Object.fromEntries(new FormData(modalForm));await onSave(values);modal.close();}catch(error){notify(error.message,true);}finally{submit.disabled=false;}};modal.showModal();}
function saveForm(resource,id,kind,initial={}){openForm(labels[kind]||kind,id?'Bearbeiten':'Neu anlegen',fields[kind](initial),async values=>{if(resource==='address-spaces'&&id&&Number(initial.network_count)>0&&values.start_ip!==initial.start_ip){await previewReplan({address_space_id:Number(id),confirm_relocation:true,operation:{action:'relocate_space',new_start_ip:values.start_ip,space_name:values.name,reserve_percent:Number(values.reserve_percent??initial.reserve_percent??25),description:values.description||'',translate_manual_starts:true}});return;}const endpoint=`${resource}${id?`/${id}`:''}`,method=id?'PATCH':'POST';try{await api(endpoint,{method,body:JSON.stringify(values)});}catch(error){if(resource!=='interfaces'||!error.message.includes('DHCP-Pool')||!confirm(`${error.message}\n\nIP-Adresse trotzdem bewusst statisch in diesem DHCP-Pool verwenden?`))throw error;await api(endpoint,{method,body:JSON.stringify({...values,confirm_dhcp_overlap:1})});}await refresh(`${labels[kind]||kind} wurde gespeichert.`);});}
function openVirtualNetwork(type='vpn',id=null,ownerHostId=null){const current=id?state.data['virtual-networks'].find(v=>Number(v.id)===Number(id))||{}:{owner_host_id:ownerHostId},kind=(current.network_type||type)==='docker_bridge'?'dockerNetwork':'vpnNetwork';openForm(kind==='dockerNetwork'?'DOCKER BRIDGE':'GLOBALES VPN',id?'Virtuelles Netz bearbeiten':'Virtuelles Netz anlegen',fields[kind](current),async values=>{await api(`virtual-networks${id?`/${id}`:''}`,{method:id?'PATCH':'POST',body:JSON.stringify({...values,network_type:kind==='dockerNetwork'?'docker_bridge':'vpn'})});await refresh('Virtuelles Netz wurde gespeichert.');});}
function openVpnInterface(id=null,networkId=null,routerId=null){const current=id?state.data['vpn-interfaces'].find(i=>Number(i.id)===Number(id))||{}:{virtual_network_id:networkId,router_id:routerId};if(!state.data['virtual-networks'].some(v=>v.network_type==='vpn')){notify('Lege zuerst in der Adressplanung ein globales VPN-Netz an.',true);return;}openForm('VPN-INTERFACE',id?'Tunnel-Interface bearbeiten':'Router mit VPN verbinden',fields.vpnInterface(current),async values=>{await api(`vpn-interfaces${id?`/${id}`:''}`,{method:id?'PATCH':'POST',body:JSON.stringify(values)});await refresh('VPN-Interface wurde gespeichert.');});}
const formWithLegacyFields=openForm;openForm=function(kicker,heading,formFields,onSave){formFields=formFields.filter(field=>!['routing_domain','vrf_name'].includes(field.name));formFields.forEach(field=>{if(field.options)field.options=field.options.map(option=>({...option,label:String(option.label||'').replace(/\s*·\s*default\s*$/,'')}));});const hostId=formFields.find(field=>field.name==='host_id')?.value,isRouter=state.data.hosts?.some(host=>Number(host.id)===Number(hostId)&&Number(host.is_router)===1),ipField=formFields.find(field=>field.name==='ip');if(isRouter&&ipField){ipField.required=false;ipField.placeholder='leer = Gateway-IP';ipField.hint='Ohne Eingabe verwendet der Router automatisch die Gateway-IP des gewählten Subnetzes.';}return formWithLegacyFields(kicker,heading,formFields,onSave);};
function saveSiteForm(id=null,initial={}){openForm('Site',id?'Bearbeiten':'Neu anlegen',fields.site(initial),async values=>{const occupied=Number(initial.area_count||0)+Number(initial.subnet_count||0)>0;if(id&&Number(initial.address_space_id)!==Number(values.address_space_id)&&occupied){const request={site_id:Number(id),target_address_space_id:Number(values.address_space_id),site:values};const preview=await api('planner/site-move-preview',{method:'POST',body:JSON.stringify(request)});setTimeout(()=>showReplanPreview(preview,request),0);return;}if(id&&occupied&&(initial.allocation_mode||'range')!==values.allocation_mode){await api(`sites/${id}`,{method:'PATCH',body:JSON.stringify({...values,allocation_mode:initial.allocation_mode||'range'})});await previewReplan({address_space_id:Number(initial.address_space_id),operation:{action:'update_site_allocation',site_id:Number(id),allocation_mode:values.allocation_mode}});return;}const site=await api(`sites${id?`/${id}`:''}`,{method:id?'PATCH':'POST',body:JSON.stringify(values)});state.selectedSpace=Number(site.address_space_id);await loadData();await render();if(!id){const space=get('address-spaces',site.address_space_id);await previewReplan({address_space_id:Number(site.address_space_id),operation:{action:'create',node_type:'leaf',parent_id:null,name:'LAN',site_id:Number(site.id),requested_hosts:0,reserve_percent:Number(space.reserve_percent??25),description:'Automatischer Startvorschlag für '+site.name}});}else notify('Site wurde gespeichert.');});}
function get(resource,id){return state.data[resource].find(x=>Number(x.id)===Number(id))||{};}
function showReplanPreview(preview,request){document.querySelector('#modal-kicker').textContent=preview.rollback?'ROLLBACK-VORSCHAU':'DYNAMISCHER REPLAN';document.querySelector('#modal-title').textContent=`Gesamtplan ${preview.effective_cidr} übernehmen`;const body=document.querySelector('#modal-body');const nodeRows=preview.node_changes.map(c=>`<tr><td>${esc(c.kind==='group'?'Gruppe':'Subnetz')} · ${esc(c.name)}</td><td class="mono">${esc(c.old||'neu')}</td><td class="mono">${esc(c.new)}</td></tr>`).join('');const ipRows=preview.address_changes.map(c=>`<tr><td>${esc(c.kind==='interface'?'Interface':'Reservierung')} · ${esc(c.name)}</td><td class="mono">${esc(c.old)}</td><td class="mono">${esc(c.new)}</td></tr>`).join('');body.innerHTML=`<div class="replan-summary"><div><span>Gesamt-CIDR</span><strong class="mono">${esc(preview.effective_cidr)}</strong></div><div><span>Dynamisches Ende</span><strong class="mono">${esc(preview.effective_end)}</strong></div><div><span>Adressänderungen</span><strong>${number(preview.address_changes.length)}</strong></div></div>${preview.warnings.length?`<div class="replan-warnings">${preview.warnings.map(w=>`<p>⚠ ${esc(w)}</p>`).join('')}</div>`:''}${nodeRows?`<div class="replan-table"><h4>Netze und Gruppen</h4><table><thead><tr><th>Objekt</th><th>Alt</th><th>Neu</th></tr></thead><tbody>${nodeRows}</tbody></table></div>`:''}${ipRows?`<div class="replan-table"><h4>Interfaces und Reservierungen</h4><table><thead><tr><th>Objekt</th><th>Alt</th><th>Neu</th></tr></thead><tbody>${ipRows}</tbody></table></div>`:''}${preview.references.length?`<div class="replan-warnings"><strong>Freitext-Verweise</strong>${preview.references.map(r=>`<p>${esc(r.ip)} in ${esc(r.kind)} „${esc(r.name)}“</p>`).join('')}</div>`:''}${preview.requires_boundary_confirmation?'<label class="boundary-confirm"><input type="checkbox" name="confirm_boundary" required> Überschreitung der privaten IPv4-Grenze ausdrücklich bestätigen</label>':''}`;const submit=document.querySelector('#modal-submit');submit.textContent=preview.rollback?'Rollback atomar übernehmen':'Replan atomar übernehmen';modalForm.onsubmit=async e=>{e.preventDefault();submit.disabled=true;try{const endpoint=preview.rollback?'planner/apply-rollback':'planner/apply-replan';const payload=preview.rollback?{run_id:preview.run_id,revision:preview.revision,plan_hash:preview.plan_hash}:{...request,revision:preview.revision,plan_hash:preview.plan_hash,confirm_boundary:Boolean(new FormData(modalForm).get('confirm_boundary'))};const result=await api(endpoint,{method:'POST',body:JSON.stringify(payload)});modal.close();if(result.created_id)state.selectedNetwork=Number(result.created_id);if(['wrap','reparent','convert_to_leaf'].includes(request.operation?.action))state.selectedNetworks.clear();await refresh(preview.rollback?'Adressplan wurde zurückgerollt.':'Dynamischer Gesamtplan wurde übernommen.');}catch(error){notify(error.message,true);}finally{submit.disabled=false;}};modal.showModal();}
const standardShowReplanPreview=showReplanPreview;
showReplanPreview=function(preview,request){if(!preview.site_move)return standardShowReplanPreview(preview,request);document.querySelector('#modal-kicker').textContent='SITE VERSCHIEBEN';document.querySelector('#modal-title').textContent='Quell- und Zielraum atomar neu planen';const rows=preview.node_changes.map(c=>`<tr><td>${esc(c.kind==='site'?'Site':c.kind==='group'?'Gruppe':'Subnetz')} · ${esc(c.name)}</td><td class="mono">${esc(c.old||'–')}</td><td class="mono">${esc(c.new||'–')}</td></tr>`).join('');document.querySelector('#modal-body').innerHTML=`<div class="replan-summary"><div><span>Quelle danach</span><strong class="mono">${esc(preview.source_effective_cidr)}</strong></div><div><span>Ziel danach</span><strong class="mono">${esc(preview.effective_cidr)}</strong></div><div><span>IP-Änderungen</span><strong>${number(preview.address_changes.length)}</strong></div></div><div class="replan-warnings">${preview.warnings.map(w=>`<p>⚠ ${esc(w)}</p>`).join('')}</div>${rows?`<div class="replan-table"><table><thead><tr><th>Objekt</th><th>Alt</th><th>Neu</th></tr></thead><tbody>${rows}</tbody></table></div>`:''}${preview.requires_boundary_confirmation?'<label class="boundary-confirm"><input type="checkbox" name="confirm_boundary" required> Überschreitung der privaten IPv4-Grenze bestätigen</label>':''}`;const submit=document.querySelector('#modal-submit');submit.textContent='Site atomar verschieben';modalForm.onsubmit=async e=>{e.preventDefault();submit.disabled=true;try{await api('planner/apply-site-move',{method:'POST',body:JSON.stringify({...request,revision:preview.revision,plan_hash:preview.plan_hash,confirm_boundary:Boolean(new FormData(modalForm).get('confirm_boundary'))})});modal.close();state.selectedSpace=Number(preview.target_address_space_id);await refresh('Site und beide Adressräume wurden atomar neu geplant.');}catch(error){notify(error.message,true);}finally{submit.disabled=false;}};modal.showModal();};
async function applyAutomaticReplan(preview,request){const result=await api('planner/apply-replan',{method:'POST',body:JSON.stringify({...request,revision:preview.revision,plan_hash:preview.plan_hash,confirm_boundary:false})});if(result.created_id)state.selectedNetwork=Number(result.created_id);if(['wrap','reparent','convert_to_leaf'].includes(request.operation?.action))state.selectedNetworks.clear();await refresh(`Automatisch übernommen · ${number(preview.address_changes.length)} IP-Änderungen · Gesamt ${preview.effective_cidr}`);preview.warnings.forEach(warning=>notify(`Hinweis: ${warning}`));}
async function previewReplan(request){const preview=await api('planner/replan-preview',{method:'POST',body:JSON.stringify(request)});preview.node_changes?.forEach(change=>{if(change.hierarchy)change.name+=` · ${change.hierarchy}`;});if(state.autoReplan&&!preview.requires_boundary_confirmation&&!preview.requires_explicit_confirmation){await applyAutomaticReplan(preview,request);return;}setTimeout(()=>showReplanPreview(preview,request),0);}
async function showReplanHistory(){const rows=await api(`planner/replans?address_space_id=${state.selectedSpace}`);document.querySelector('#modal-kicker').textContent='REPLAN-HISTORIE';document.querySelector('#modal-title').textContent='Änderungsverlauf';document.querySelector('#modal-body').innerHTML=`<div class="replan-table">${rows.length?`<table><thead><tr><th>Lauf</th><th>Zeitpunkt</th><th>Revision</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>#${r.id}</td><td>${esc(r.created_at)}</td><td class="mono">${esc(r.revision_after.slice(0,10))}</td><td><button type="button" class="button small secondary" data-action="rollback-preview" data-id="${r.id}">Rollback prüfen</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Noch kein Replan übernommen.</div>'}</div>`;document.querySelector('#modal-submit').textContent='Schließen';modalForm.onsubmit=e=>{e.preventDefault();modal.close();};modal.showModal();}
function openNetworkPlan(kind='leaf',root=false,options={}){
  const parent=options.parentId?state.data.networks.find(n=>Number(n.id)===Number(options.parentId)):(root?null:state.data.networks.find(n=>Number(n.id)===Number(state.selectedNetwork)));if(parent)state.selectedSpace=Number(parent.address_space_id);if(!state.selectedSpace&&state.data['address-spaces'][0])state.selectedSpace=Number(state.data['address-spaces'][0].id);if(!state.selectedSpace){notify('Lege zuerst einen Adressraum an.',true);return;}
  const siteId=options.siteId??parent?.site_id??'',space=get('address-spaces',state.selectedSpace),siteOptions=state.data.sites.filter(s=>Number(s.address_space_id)===Number(state.selectedSpace));if(!siteId&&siteOptions.length===0){notify('Lege in diesem Adressraum zuerst eine Site an.',true);return;}const form=[{name:'name',label:kind==='leaf'?'Subnetzname':'Gruppenname',required:true},{name:'site_id',label:'Site',type:'select',value:siteId,options:siteOptions.map(s=>({value:s.id,label:`${s.name} · ${s.domain_name}`})),required:true,hint:'Netze können nicht siteübergreifend angelegt werden.'},...(kind==='leaf'?[{name:'prefix',label:'Optionaler fester Präfix',value:'',placeholder:'/24',hint:'Leer lassen: Der Planer bestimmt die Größe dynamisch und lässt das Subnetz mitwachsen.'},{name:'start_ip',label:'Optionale feste Start-IP',value:'',placeholder:'172.20.1.64',hint:'Leer lassen: Der Planer platziert das Subnetz automatisch. Die Adresse muss zur berechneten CIDR-Größe ausgerichtet sein.'},{name:'requested_hosts',label:'Optional geplanter Hostbedarf',type:'number',value:0,hint:'Tatsächliche Belegung und Reserve bestimmen den Mindestbedarf.'},{name:'reserve_percent',label:'Reserve (%)',type:'number',value:space.reserve_percent??25},{name:'vlan_id',label:'VLAN-ID',type:'number'},{name:'vrf_name',label:'Netz-VRF / Kennzeichnung'}]:[]),{name:'description',label:'Beschreibung',type:'textarea',wide:true}];openForm('DYNAMISCHER PLANER',kind==='leaf'?'Subnetz anlegen':'Optionale Gruppe anlegen',form,async values=>{await previewReplan({address_space_id:Number(state.selectedSpace),operation:{action:'create',node_type:kind,parent_id:parent?.id||null,name:values.name,site_id:Number(values.site_id),prefix:values.prefix||'',...(kind==='leaf'?{start_ip:values.start_ip||''}:{}),requested_hosts:Number(values.requested_hosts||0),reserve_percent:Number(values.reserve_percent??space.reserve_percent??25),vlan_id:values.vlan_id||null,vrf_name:values.vrf_name||'',description:values.description||''}});});
}
function editDynamicNetwork(id){const network=get('networks',id),role=networkRole(network);openForm('DYNAMISCHER REPLAN',`${networkRoleLabel(network)} bearbeiten`,fields.network(network),async values=>{await previewReplan({address_space_id:Number(network.address_space_id),operation:{action:'update',id,name:values.name,site_id:values.site_id||null,...(role!=='group'?{prefix:values.prefix||''}:{}),...(['subnet','aggregate'].includes(role)?{start_ip:values.start_ip||''}:{}),requested_hosts:Number(values.requested_hosts||0),reserve_percent:Number(values.reserve_percent||0),vlan_id:values.vlan_id||null,vrf_name:values.vrf_name||'',description:values.description||''}});});}
function convertContainerRole(id,targetRole){const network=get('networks',id);if(!network.id)return;if(targetRole==='aggregate'){openForm('HIERARCHIE','Gruppe in Supernetz umwandeln',[{name:'prefix',label:'Optionaler fester Supernetz-Präfix',placeholder:'/20',hint:'Leer lassen: Das Supernetz wächst dynamisch anhand seiner Kinder.'},{name:'notice',label:'Auswirkung',value:'Kinder, Reihenfolge und Site bleiben erhalten.',disabled:true,wide:true}],async values=>{await previewReplan({address_space_id:Number(network.address_space_id),operation:{action:'convert_container_role',id,target_role:'aggregate',prefix:values.prefix||''}});});return;}openForm('HIERARCHIE','Supernetz in Gruppe umwandeln',[{name:'notice',label:'Auswirkung',value:'Kinder, Reihenfolge und Site bleiben erhalten. Die feste CIDR-Hülle und das Gateway des Supernetzes entfallen.',disabled:true,wide:true}],async()=>{await previewReplan({address_space_id:Number(network.address_space_id),operation:{action:'convert_container_role',id,target_role:'group'}});});}
function activateL3(id){const network=get('networks',id),gateway=network.gateway||intToIp(ipToInt(network.network||network.cidr.split('/')[0])+1);openForm('GEMEINSAMES L3-NETZ','Supernetz als gemeinsames Layer-3-Subnetz aktivieren',[{name:'cidr',label:'Festes L3-CIDR',value:network.cidr,disabled:true},{name:'gateway',label:'Gemeinsames Gateway',value:gateway,required:true,hint:'Diese Adresse gilt für alle untergeordneten Pools.'},{name:'pool_type',label:'Anfänglicher Typ der Kindbereiche',type:'select',value:'static_pool',options:[{value:'static_pool',label:'Statische Adresspools'},{value:'dhcp_pool',label:'DHCP-Adresspools'}],required:true},{name:'vlan_id',label:'VLAN-ID',type:'number',value:network.vlan_id},{name:'notice',label:'Auswirkung',value:'Kindsubnetze werden zu Pools; vorhandene IPs bleiben erhalten.',disabled:true,wide:true}],async values=>{await previewReplan({address_space_id:Number(network.address_space_id),operation:{action:'activate_l3',id,gateway:values.gateway,pool_type:values.pool_type,vlan_id:values.vlan_id||null}});});}
function editPool(id){const pool=get('networks',id),fixed=Number(pool.pool_range_fixed)===1;openForm('ADRESSPOOL',`${networkRoleLabel(pool)} bearbeiten`,[{name:'pool_type',label:'Pooltyp',type:'select',value:pool.allocation_type,options:[{value:'static_pool',label:'Statischer Pool'},{value:'dhcp_pool',label:'DHCP-Pool'}],required:true},{name:'prefix',label:'Optionaler Präfix',value:pool.manual_prefix===null||pool.manual_prefix===undefined?'':`/${pool.manual_prefix}`,placeholder:'/26',hint:'Leer lassen: Die CIDR-Hülle wächst automatisch mit der Belegung.'},{name:'range_start',label:'Optionaler fixer Bereich von',value:fixed?pool.range_start:'',placeholder:pool.range_start,hint:'Beide Bereichsgrenzen leer lassen, damit der Pool die gesamte dynamische CIDR-Hülle nutzt.'},{name:'range_end',label:'Optionaler fixer Bereich bis',value:fixed?pool.range_end:'',placeholder:pool.range_end,hint:'Nur gemeinsam mit „Bereich von“ angeben.'}],async values=>{await previewReplan({address_space_id:Number(pool.address_space_id),operation:{action:'update_pool',id,pool_type:values.pool_type,prefix:values.prefix||'',range_start:values.range_start||'',range_end:values.range_end||''}});});}
function addPool(id){const parent=get('networks',id);openForm('ADRESSPOOL','Pool im gemeinsamen L3-Netz anlegen',[{name:'name',label:'Poolname',required:true},{name:'pool_type',label:'Pooltyp',type:'select',value:'static_pool',options:[{value:'static_pool',label:'Statischer Pool'},{value:'dhcp_pool',label:'DHCP-Pool'}],required:true},{name:'prefix',label:'Optionaler Präfix',placeholder:'/26',hint:'Leer lassen: CIDR und Poolbereich wachsen dynamisch anhand der Belegung.'},{name:'range_start',label:'Optionaler fixer Bereich von',placeholder:'172.20.1.64',hint:'Leer lassen, um den nutzbaren Bereich automatisch aus der CIDR-Hülle zu berechnen.'},{name:'range_end',label:'Optionaler fixer Bereich bis',placeholder:'172.20.1.126',hint:'Nur gemeinsam mit „Bereich von“ angeben.'},{name:'description',label:'Beschreibung',type:'textarea',wide:true}],async values=>{await previewReplan({address_space_id:Number(parent.address_space_id),operation:{action:'create',node_type:'leaf',allocation_type:values.pool_type,parent_id:id,name:values.name,site_id:Number(parent.site_id),prefix:values.prefix||'',range_start:values.range_start||'',range_end:values.range_end||'',requested_hosts:0,reserve_percent:0,description:values.description||''}});});}
function selectedNetworks(){return[...state.selectedNetworks].map(id=>get('networks',id)).filter(n=>n.id);}
function openNetworkWrap(){const selected=selectedNetworks();if(selected.length<2){notify('Wähle mindestens zwei Gruppen oder Subnetze aus.',true);return;}openForm('HIERARCHIE','Auswahl zusammenfassen',[{name:'wrapper_role',label:'Neue Hülle',type:'select',value:'group',options:[{value:'group',label:'Organisatorische Gruppe'},{value:'aggregate',label:'Übergeordnetes Subnetz / Supernetz'}],required:true},{name:'name',label:'Name',required:true},{name:'prefix',label:'Optionaler Supernetz-Präfix',placeholder:'/20',hint:'Nur für Supernetze. Leer bedeutet dynamisches Wachstum.'},{name:'description',label:'Beschreibung',type:'textarea',wide:true}],async values=>{await previewReplan({address_space_id:Number(selected[0].address_space_id),operation:{action:'wrap',ids:selected.map(n=>Number(n.id)),wrapper_role:values.wrapper_role,name:values.name,prefix:values.wrapper_role==='aggregate'?(values.prefix||''):'',description:values.description||''}});});}
function openNetworkMove(){const selected=selectedNetworks();if(!selected.length){notify('Wähle mindestens ein Netzobjekt aus.',true);return;}const siteId=Number(selected[0].site_id),excluded=new Set(selected.map(n=>Number(n.id))),networks=state.data.networks.filter(n=>Number(n.site_id)===siteId&&!excluded.has(Number(n.id))),targets=[{value:'root',label:'Oberste Ebene · hinten anreihen'}];networks.forEach(n=>{const label=siteOptionLabel(n,`${networkRoleLabel(n)} „${n.name}“ · ${n.cidr}`);targets.push({value:`inside:${n.id}`,label:`In ${label} verschachteln`},{value:`before:${n.id}`,label:`Vor ${label} einfügen`},{value:`after:${n.id}`,label:`Nach ${label} einfügen`});});openForm('HIERARCHIE','Auswahl verschieben oder umreihen',[{name:'target',label:'Zielposition',type:'select',value:'root',options:targets,required:true,hint:'„In“ verschachtelt. „Vor“ und „Nach“ ändern die Reihenfolge auf derselben Ebene.'}],async values=>{const operation={action:'reparent',ids:selected.map(n=>Number(n.id)),parent_id:null};if(values.target!=='root'){const[mode,idText]=values.target.split(':'),target=get('networks',Number(idText));if(mode==='inside')operation.parent_id=Number(target.id);else{operation.parent_id=target.parent_id||null;operation.anchor_id=Number(target.id);operation.position=mode;}}await previewReplan({address_space_id:Number(selected[0].address_space_id),operation});});}
async function openPlannedHost(preselected){let siteId=preselected?.site_id||null,candidates=[];if(siteId)candidates=await api(`planner/host-candidates?site_id=${siteId}`);else for(const site of state.data.sites){const found=await api(`planner/host-candidates?site_id=${site.id}`);if(found.length){siteId=site.id;candidates=found;break;}}if(!siteId){notify('Lege zuerst eine Site an.',true);return;}if(!candidates.length){if(confirm('Kein passendes Blatt-Subnetz oder statischer Pool verfügbar. Jetzt ein mathematisch passendes Host-Subnetz planen?'))openNetworkPlan('leaf',true,{siteId});return;}const candidateValue=c=>`${c.network_id}:${c.pool_id||''}`,preferred=candidates.find(c=>Number(c.pool_id||c.network_id)===Number(preselected?.id));openForm('HOSTPLATZIERUNG','Host und IP anlegen',[{name:'placement',label:'Vorgeschlagenes Subnetz / Pool und nächste IP',type:'select',value:candidateValue(preferred||candidates[0]),options:candidates.map(c=>({value:candidateValue(c),label:siteOptionLabel(c,`${c.pool_id?'Statischer Pool':'Subnetz'} · ${c.network_name} · ${c.cidr} → ${c.ip}`)})),required:true},{name:'name',label:'Anzeigename',required:true},{name:'hostname',label:'Technischer Hostname / FQDN',placeholder:'mail-01 oder office.example.at.',required:true,hint:'Kurzname nutzt die Site-Domain; ein abschließender Punkt kennzeichnet einen absoluten FQDN.'},{name:'aliases',label:'DNS-Aliase',type:'textarea',wide:true},{name:'type',label:'Typ',type:'select',value:'server',options:['server','vm','network','client','appliance','other'].map(x=>({value:x,label:x}))},{name:'status',label:'Status',type:'select',value:'planned',options:['planned','active','degraded','inactive'].map(x=>({value:x,label:labels[x]}))},{name:'interface_name',label:'Interface',value:'eth0'}],async v=>{const[networkId,poolId]=v.placement.split(':');await api('planner/apply-host',{method:'POST',body:JSON.stringify({network_id:Number(networkId),pool_id:poolId?Number(poolId):null,interface_name:v.interface_name,host:{name:v.name,hostname:v.hostname,aliases:v.aliases,type:v.type,status:v.status}})});await refresh('Host wurde mit der nächsten freien IP angelegt.');});}
async function selectNetwork(id){state.selectedNetwork=Number(id);state.analysis=null;renderIpam();state.analysis=await api(`planner/analyze/${id}`);renderIpam();}
function openVlsm(){openForm('SUBNETZPLANER','VLSM-Plan erstellen',[{name:'requests',label:'Subnetze – eine Zeile je Netz',type:'textarea',wide:true,required:true,hint:'Format: Name, Hostanzahl oder Name, /Präfix · Beispiel: Clients, 120'}],async values=>{const requests=values.requests.split('\n').map(line=>line.trim()).filter(Boolean).map(line=>{const [name,size]=line.split(',').map(x=>x.trim());if(!name||!size)throw new Error(`Ungültige Zeile: ${line}`);return size.startsWith('/')?{name,prefix:Number(size.slice(1))}:{name,hosts:Number(size)};});const plan=await api(`blocks/${state.selectedBlock}/plan`,{method:'POST',body:JSON.stringify({requests})});const list=plan.proposals.map(p=>`${p.name}: ${p.cidr} (${number(p.usable)} nutzbar)`).join('\n');if(!confirm(`Vorschlag:\n\n${list}\n\n${number(plan.remaining)} Adressen verbleiben. Plan übernehmen?`))return;await api(`blocks/${state.selectedBlock}/apply-plan`,{method:'POST',body:JSON.stringify({requests})});await refresh('VLSM-Plan wurde vollständig übernommen.');});}
function hostSpreadsheetValues(row){const values={};for(const field of row.querySelectorAll('[data-host-field]')){if(field.required&&!field.value.trim()){field.focus();field.reportValidity();throw new Error('Name, Hostname und Site sind erforderlich.');}values[field.dataset.hostField]=field.value;}return{...values,site_id:Number(values.site_id),notes:'',aliases:[]};}
async function saveHostSpreadsheetRow(row){const id=Number(row.dataset.hostRow),host=get('hosts',id);if(!host.id)throw new Error('Host wurde nicht gefunden.');const values=hostSpreadsheetValues(row);row.classList.add('saving');try{await api(`hosts/${id}`,{method:'PATCH',body:JSON.stringify({...values,notes:host.notes||'',aliases:(host.aliases||[]).map(alias=>alias.input_name)})});await loadData();renderHosts();notify(`Host „${values.name}“ wurde gespeichert.`);}catch(error){row.classList.remove('saving');throw error;}}
async function createHostSpreadsheetRow(row){const values=hostSpreadsheetValues(row);row.classList.add('saving');try{await api('hosts',{method:'POST',body:JSON.stringify(values)});await loadData();renderHosts();document.querySelector('[data-host-new-row] [data-host-field="name"]')?.focus();notify(`Host „${values.name}“ wurde angelegt. Über „IP +“ kannst du direkt ein Interface ergänzen.`);}catch(error){row.classList.remove('saving');throw error;}}

document.addEventListener('click',async e=>{
  const button=e.target.closest('button');if(!button)return;const a=button.dataset.action,id=Number(button.dataset.id||0);
  if(contextMenu.contains(button))closeContextMenu();
  try{
    if(button.dataset.copyValue!==undefined){await copyText(button.dataset.copyValue);return;}
    if(button.dataset.copyMode){await copyText(calculatorCopyText(button.dataset.copyMode));return;}
    if(a==='host-view-cards'||a==='host-view-table'){state.hostView=saveHostView(a==='host-view-table'?'table':'cards');renderHosts();return;}
    if(a==='host-filter-reset'){state.hostFilters={q:'',site:'',type:'',status:''};renderHosts();return;}
    if(a==='host-row-save'){await saveHostSpreadsheetRow(button.closest('[data-host-row]'));return;}
    if(a==='host-row-create'){await createHostSpreadsheetRow(button.closest('[data-host-new-row]'));return;}
    if(a==='router-add')saveForm('routers',null,'router');if(a==='router-edit')saveForm('routers',id,'router',state.data.routers.find(r=>Number(r.id)===id)||{});if(a==='router-select'){state.selectedRouter=id;renderRouters();}
    if(a==='virtual-network-add')openVirtualNetwork(button.dataset.kind||'vpn');if(a==='virtual-network-edit')openVirtualNetwork('vpn',id);if(a==='docker-network-add')openVirtualNetwork('docker_bridge',null,id);if(a==='vpn-interface-edit')openVpnInterface(id);if(a==='vpn-interface-add'){const networkId=Number(button.dataset.network||0)||(button.dataset.kind==='router'?null:id||null),routerId=Number(button.dataset.router||0)||(button.dataset.kind==='router'?id:null);openVpnInterface(null,networkId,routerId);}
    if(a==='router-interface-add')saveForm('interfaces',null,'interface',{host_id:id,name:'eth0'});if(a==='route-add')saveForm('static-routes',null,'route',{router_id:id});if(a==='route-edit'){const route=state.data.routers.flatMap(r=>r.routes).find(r=>Number(r.id)===id);if(route)saveForm('static-routes',id,'route',route);}if(a==='route-suggest')await showRouteSuggestions(id);
    if(a==='route-accept'){const rows=JSON.parse(modal.dataset.suggestions||'[]'),suggestion=rows[Number(button.dataset.index)];if(suggestion){modal.close();saveForm('static-routes',null,'route',suggestion);}}
    if(a==='site-add')saveSiteForm(null,{address_space_id:Number(button.dataset.space||state.selectedSpace||0)});if(a==='space-add')saveForm('address-spaces',null,'space');if(a==='space-edit')saveForm('address-spaces',id,'space',get('address-spaces',id));if(a==='block-add')saveForm('blocks',null,'block');if(a==='subnet-add')saveForm('subnets',null,'subnet',{block_id:state.selectedBlock});if(a==='host-add')await openPlannedHost();if(a==='service-add')saveForm('services',null,'service',id?{host_id:id}:{});if(a==='relation-add')saveForm('relations',null,'relation');if(a==='reservation-add')saveForm('reservations',null,'reservation',{network_id:id});if(a==='interface-add')saveForm('interfaces',null,'interface',{host_id:id});
    if(a==='block-edit')saveForm('blocks',id,'block',get('blocks',id));if(a==='subnet-edit')saveForm('subnets',id,'subnet',get('subnets',id));if(a==='host-edit')saveForm('hosts',id,'host',get('hosts',id));if(a==='service-edit')saveForm('services',id,'service',get('services',id));
    if(a==='site-edit')saveSiteForm(id,get('sites',id));if(a==='interface-edit')saveForm('interfaces',id,'interface',get('interfaces',id));if(a==='reservation-edit')saveForm('reservations',id,'reservation',get('reservations',id));if(a==='relation-edit')saveForm('relations',id,'relation',get('relations',id));
    if(a==='site-ipam')go('ipam',{site:id});if(a==='site-topology')go('topology',{site:id});if(a==='site-filter-clear')go('ipam');
    if(a==='block-select'){state.selectedBlock=id;state.selectedSubnet=null;renderIpam();}if(a==='vlsm')openVlsm();
    if(a==='space-select'){state.selectedSpace=id;state.selectedNetwork=null;state.selectedNetworks.clear();state.analysis=null;renderIpam();}if(a==='network-select')await selectNetwork(id);if(a==='network-plan')openNetworkPlan(button.dataset.kind||'leaf',button.dataset.root==='1',{siteId:button.dataset.site?Number(button.dataset.site):undefined});if(a==='planned-host')await openPlannedHost(get('networks',id));
    if(a==='network-wrap')openNetworkWrap();if(a==='network-move')openNetworkMove();if(a==='network-selection-clear'){state.selectedNetworks.clear();renderIpam();}if(a==='network-convert-role')convertContainerRole(id,button.dataset.role||button.dataset.kind);if(a==='network-convert-leaf'){const network=get('networks',id);await previewReplan({address_space_id:Number(network.address_space_id),operation:{action:'convert_to_leaf',id}});}
    if(a==='dynamic-network-edit'){const network=get('networks',id);if(['static_pool','dhcp_pool'].includes(networkRole(network)))editPool(id);else editDynamicNetwork(id);}
    if(a==='network-activate-l3')activateL3(id);if(a==='pool-add')addPool(id);if(a==='network-deactivate-l3'){const network=get('networks',id);if(confirm('L3-Modus deaktivieren? Dies ist nur möglich, wenn das Netz und alle Pools leer sind.'))await previewReplan({address_space_id:Number(network.address_space_id),operation:{action:'deactivate_l3',id}});}
    if(a==='replan-current')await previewReplan({address_space_id:Number(state.selectedSpace),operation:{action:'none'}});
    if(a==='replan-history')await showReplanHistory();
    if(a==='rollback-preview'){const preview=await api(`planner/rollback-preview/${id}`);modal.close();setTimeout(()=>showReplanPreview(preview,{run_id:id}),0);}
    if(a==='network-expand'){if(confirm('Netz ohne Änderung bestehender IPs auf den freien Buddy-Bereich erweitern?')){await api(`networks/${id}/expand`,{method:'POST',body:'{}'});await refresh('Netz wurde erweitert.');await selectNetwork(id);}}
    if(a==='network-split'){const parts=Number(button.dataset.parts);if(confirm(`Netz in ${parts} gleich große Subnetze teilen? Bestehende IPs werden ohne Umnummerierung zugeordnet.`)){await api(`networks/${id}/split`,{method:'POST',body:JSON.stringify({parts})});await refresh('Netz wurde aufgeteilt.');await selectNetwork(id);}}
    if(a==='positions-save'){await api('topology/positions',{method:'POST',body:JSON.stringify({scope:state.topology.scope,positions:state.topology.nodes.map(n=>({entity_id:n.id,x:n.x,y:n.y}))})});notify('Topologiepositionen wurden gespeichert.');}
    if(a==='positions-auto')autoLayout();
    if(a==='topology-zoom-in')zoomTopology(.8);
    if(a==='topology-zoom-out')zoomTopology(1.25);
    if(a==='topology-fit')fitTopologyViewport();
    if(a==='topology-expand'){document.body.classList.toggle('topology-fullscreen');button.textContent=document.body.classList.contains('topology-fullscreen')?'⊟ Vollbild verlassen':'⛶ Arbeitsfläche maximieren';}
    if(a==='positions-reset'){if(confirm('Gespeicherte Positionen für diese Ansicht zurücksetzen?')){await api(`topology/positions?scope=${encodeURIComponent(state.topology.scope)}`,{method:'DELETE'});await renderTopology();notify('Positionen wurden zurückgesetzt.');}}
    if(a==='relation-cancel')cancelRelation();
    if(a==='relation-start'){const node=state.topology?.nodes.find(n=>Number(n.id)===id);if(node)startRelation(node);}
    if(a==='topology-site-add'){const node=state.topology?.nodes.find(n=>Number(n.id)===id);if(node?.kind==='address_space')saveSiteForm(null,{address_space_id:node.object_id});}
    if(a==='topology-router-open'){state.selectedRouter=id;go('routers');}
    if(a==='topology-open'){
      const node=state.topology?.nodes.find(n=>Number(n.id)===id);if(node){state.focusId=id;state.query=node.name;search.value=node.name;if(node.kind==='address_space'){state.selectedSpace=Number(node.object_id);go('ipam');}if(node.kind==='virtual_network')go('ipam');if(node.kind==='site')go('sites');if(node.kind==='block'||node.kind==='subnet'){const network=get('networks',id);state.selectedSpace=Number(network.address_space_id);state.selectedNetwork=id;state.analysis=null;go('ipam',network.site_id?{site:network.site_id}:{});}if(node.kind==='host')go('hosts');if(node.kind==='service')go('services');}
    }
    if(a==='topology-edit'){
      const node=state.topology?.nodes.find(n=>Number(n.id)===id);if(node?.kind==='address_space')saveForm('address-spaces',node.object_id,'space',get('address-spaces',node.object_id));if(node?.kind==='virtual_network')openVirtualNetwork(node.virtual_role,id);if(node?.kind==='site')saveSiteForm(id,get('sites',id));if(node?.kind==='block'||node?.kind==='subnet'){if(['static_pool','dhcp_pool'].includes(node.node_role))editPool(id);else editDynamicNetwork(id);}if(node?.kind==='host')saveForm('hosts',id,'host',get('hosts',id));if(node?.kind==='service')saveForm('services',id,'service',get('services',id));
    }
    if(a==='topology-network-plan'){const node=state.topology?.nodes.find(n=>Number(n.id)===id);if(node?.kind==='site')openNetworkPlan(button.dataset.kind||'leaf',true,{siteId:id});else if(node){const network=get('networks',id);state.selectedSpace=Number(network.address_space_id);state.selectedNetwork=id;openNetworkPlan(button.dataset.kind||'leaf',false,{parentId:id,siteId:network.site_id||''});}}
    if(a==='topology-host-add'){const node=state.topology?.nodes.find(n=>Number(n.id)===id);if(node?.kind==='site')await openPlannedHost({site_id:id});if(node?.kind==='subnet')await openPlannedHost(get('networks',id));}
    if(button.dataset.delete){if(!confirm('Datensatz wirklich löschen? Abhängige Objekte können das Löschen verhindern.'))return;if(button.dataset.delete==='networks'){const network=get('networks',id);await previewReplan({address_space_id:Number(network.address_space_id),operation:{action:'delete',id}});return;}await api(`${button.dataset.delete}/${id}`,{method:'DELETE'});await refresh('Datensatz wurde gelöscht.');}
  }catch(error){notify(error.message,true);}
});
document.addEventListener('click',e=>{const row=e.target.closest('[data-subnet]');if(row&&!e.target.closest('button')){state.selectedSubnet=Number(row.dataset.subnet);renderIpam();}});
document.querySelector('.mobile-menu').addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'));
document.querySelectorAll('.modal-cancel').forEach(button=>button.addEventListener('click',()=>modal.close()));
document.querySelectorAll('.sidebar a').forEach(a=>a.addEventListener('click',()=>document.querySelector('.sidebar').classList.remove('open')));
document.addEventListener('change',e=>{if(e.target.id==='auto-replan'){state.autoReplan=saveAutoReplan(e.target.checked);notify(state.autoReplan?'Automatische Replan-Übernahme aktiviert.':'Automatische Replan-Übernahme deaktiviert.');return;}if(e.target.matches('[data-host-field]')){e.target.closest('[data-host-row],[data-host-new-row]')?.classList.add('dirty');return;}const hostFilter={"host-filter-site":'site',"host-filter-type":'type',"host-filter-status":'status'}[e.target.id];if(hostFilter){state.hostFilters[hostFilter]=e.target.value;renderHosts();return;}if(e.target.matches('[data-network-check]')){const id=Number(e.target.dataset.networkCheck);if(e.target.checked)state.selectedNetworks.add(id);else state.selectedNetworks.delete(id);renderIpam();return;}if(e.target.id==='topology-site')go('topology',e.target.value?{site:e.target.value}:{});if(e.target.id==='ipam-site'){state.selectedNetworks.clear();go('ipam',e.target.value?{site:e.target.value}:{});}});
document.addEventListener('input',e=>{if(e.target.matches('[data-host-field]')){e.target.closest('[data-host-row],[data-host-new-row]')?.classList.add('dirty');return;}if(e.target.id==='host-filter-text'){const position=e.target.selectionStart??e.target.value.length;state.hostFilters.q=e.target.value;renderHosts();const input=document.querySelector('#host-filter-text');input?.focus();input?.setSelectionRange(position,position);}});
document.addEventListener('submit',async e=>{const form=e.target.closest('.calculator-form');if(!form)return;e.preventDefault();const button=form.querySelector('[type="submit"]');button.disabled=true;try{const values=Object.fromEntries(new FormData(form));values.mode=form.dataset.calculatorMode;const result=await api('tools/ipv4',{method:'POST',body:JSON.stringify(values)});renderCalculatorResult(values.mode,result);}catch(error){notify(error.message,true);}finally{button.disabled=false;}});
let draggedNetwork=null;
document.addEventListener('dragstart',e=>{if(e.target.closest('.network-check')){e.preventDefault();return;}const row=e.target.closest('[data-network-row]');if(!row)return;draggedNetwork=Number(row.dataset.networkRow);document.body.classList.add('network-dragging');row.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(draggedNetwork));});
document.addEventListener('dragover',e=>{const target=e.target.closest('[data-drop-mode],[data-site-drop]');if(!target||!draggedNetwork)return;e.preventDefault();document.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));target.classList.add('drop-target');});
document.addEventListener('dragleave',e=>{const target=e.target.closest('[data-drop-mode],[data-site-drop]');if(target&&!target.contains(e.relatedTarget))target.classList.remove('drop-target');});
document.addEventListener('drop',async e=>{const dropTarget=e.target.closest('[data-drop-mode]'),siteTarget=e.target.closest('[data-site-drop]');if((!dropTarget&&!siteTarget)||!draggedNetwork)return;e.preventDefault();document.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));document.body.classList.remove('network-dragging');const source=get('networks',draggedNetwork),ids=state.selectedNetworks.has(draggedNetwork)?[...state.selectedNetworks]:[draggedNetwork];if(!source.id){draggedNetwork=null;return;}let operation;if(siteTarget&&!dropTarget){if(Number(siteTarget.dataset.siteDrop)!==Number(source.site_id)){notify('Netzobjekte können nicht per Drag-and-drop zwischen Sites verschoben werden.',true);draggedNetwork=null;return;}operation={action:'reparent',ids,parent_id:null};}else{const targetId=Number(dropTarget.dataset.dropId),mode=dropTarget.dataset.dropMode,target=get('networks',targetId);operation=mode==='inside'?{action:'reparent',ids,parent_id:targetId}:{action:'reparent',ids,parent_id:target.parent_id||null,anchor_id:targetId,position:mode};}draggedNetwork=null;try{await previewReplan({address_space_id:Number(source.address_space_id),operation});}catch(error){notify(error.message,true);}});
document.addEventListener('dragend',()=>{draggedNetwork=null;document.body.classList.remove('network-dragging');document.querySelectorAll('.dragging,.drop-target').forEach(el=>el.classList.remove('dragging','drop-target'));});
document.addEventListener('pointerdown',e=>{if(!contextMenu.hidden&&!contextMenu.contains(e.target))closeContextMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)&&e.target.matches('[data-host-field]')){e.preventDefault();const row=e.target.closest('[data-host-row],[data-host-new-row]');row?.querySelector('[data-action="host-row-save"],[data-action="host-row-create"]')?.click();return;}if(e.key==='Escape'){if(!contextMenu.hidden)closeContextMenu();else if(state.relationSource)cancelRelation();else if(document.body.classList.contains('topology-fullscreen')){document.body.classList.remove('topology-fullscreen');const button=document.querySelector('[data-action="topology-expand"]');if(button)button.textContent='⛶ Arbeitsfläche maximieren';}}});
window.addEventListener('scroll',closeContextMenu,true);
search.addEventListener('input',()=>{state.query=search.value.trim();if(['sites','hosts','services','relations'].includes(state.view))render();});
window.addEventListener('hashchange',()=>render().catch(error=>notify(error.message,true)));
function ipToInt(ip){return ip.split('.').reduce((n,p)=>n*256+Number(p),0);}function intToIp(n){return [24,16,8,0].map(s=>(Math.floor(n/2**s)%256)).join('.');}

loadData().then(render).catch(error=>{app.innerHTML=`<div class="panel empty">${esc(error.message)}</div>`;notify(error.message,true);});
